INSERT INTO hospitals (id,code,name,short_name,address,emergency_phone,status,updated_at) VALUES ('hospital-qbj','QBJRMYY','成都市青白江区人民医院','青白江区人民医院','四川省成都市青白江区凤凰东四路9号','028-83611120','active','2026-08-28T00:00:00+08:00') ON CONFLICT(id) DO UPDATE SET code=excluded.code,name=excluded.name,short_name=excluded.short_name,address=excluded.address,emergency_phone=excluded.emergency_phone,status='active',updated_at=excluded.updated_at;
INSERT INTO departments (id,hospital_id,code,name,aliases,floor,zone,description,specialty,status,sort_order,updated_at) VALUES
('dept-qbj-icu','hospital-qbj','ICU','重症医学科','[]','住院区域','重症监护区','重症医学科（ICU）是青白江区首家集危重症抢救、监护及综合性治疗的重症监护治疗中心。科室集中医院优势医疗资源对急危重症患者进行救治，开展各类急性器官功能衰竭、需紧急生命支持患者，各类休克、中毒患者，严重多发伤、复合伤患者，呼吸心跳骤停需心肺脑复苏患者，各种重大、高危手术需围手术期监护、处理患者，严重、复杂感染，脓毒血症，重症急性胰腺炎，多器官功能衰竭等患者的精心监测和精确治疗，对各类危重患者抢救积累了丰富的临床经验，并抢救成功了大量的危重患者。专业特色：器官功能支持、急危重症患者监测等。','持续血液净化治疗（CBP）、重症血流动力学监测与治疗、机械通气技术','active',1,'2026-08-28T00:00:00+08:00'),
('dept-qbj-radiology','hospital-qbj','RADIOLOGY','医学影像科','[]','医技楼 1F','影像检查区','医学影像科是区域规模最大、技术力量最雄厚、设备最先进的医学影像检查中心，是青白江区远程影像会诊中心。科室设备总资产近4000万元。拥有128层容积VCT、1.5T超导磁共振、整板数字DR机、数字乳腺钼靶摄片系统、动态数字胃肠机、数字双能X线骨密度仪、床旁DR机等进口设备；还拥有国产64层多层螺旋CT、数字DR机等先进设备及图像处理工作站；有自助打印激光相机3台。科室建立了图像储存和传输系统（PACS）和影像信息系统（RIS），已成为数字化、网络化现代医学影像中心。','医学影像科是区域规模最大、技术力量最雄厚、设备最先进的医学影像检查中心，是青白江区远程影像会诊中心。科室设备总资产近4000万元。拥有128层容积VCT、1.5T超导磁共振、整板数字DR机、数字乳腺钼靶摄片系统、动态数字胃肠机、数字双能X线骨密度仪、床旁DR机等进口设备；还拥有国产64层多层螺旋CT、数字DR机等先进设备及图像处理工作站；有自助打印激光相机3台。科室建立了图像储存和传输系统（PACS）和影像信息系统（RIS），已成为数…','active',2,'2026-08-28T00:00:00+08:00'),
('dept-qbj-cssd','hospital-qbj','CSSD','消毒供应中心','[]','医技楼 1F','院内工作区','消毒供应中心建筑面积865平方米，布局合理，区域划分明确，功能齐全，配备了现代化的清洗、消毒、灭菌设备，为医疗质量安全、预防医院感染提供安全保障。中心于2015年2月通过市卫生主管部门质量评价验收。','消毒供应中心建筑面积865平方米，布局合理，区域划分明确，功能齐全，配备了现代化的清洗、消毒、灭菌设备，为医疗质量安全、预防医院感染提供安全保障。中心于2015年2月通过市卫生主管部门质量评价验收。 主要设备：低温等离子灭菌设备、内窥镜清洗设备、超声波清洗机、全自动喷淋式清洗机、脉动真空灭菌器、煮沸槽、干燥柜等；另有全自动水处理系统、酸性氧化电位水、带光源放大镜的器械检查打包台、包装材料切割机、医用热封机、压力水枪、压力气枪、快速生物…','active',3,'2026-08-28T00:00:00+08:00'),
('dept-qbj-ultrasound','hospital-qbj','ULTRASOUND','超声科','[]','医技楼 2F','超声检查区','超声科现有医护人员24名，其中主任医师1名，副主任医师1名，主治医师13名，医师3名，护师1名，技师5名，多人曾在华西第一医院、华西第二医院、四川省人民医院、成都市第二人民医院等上级医院进修学习。','医师13名，医师3名，护师1名，技师5名，多人曾在华西第一医院、华西第二医院、四川省人民医院、成都市第二人民医院等上级医院进修学习','active',4,'2026-08-28T00:00:00+08:00'),
('dept-qbj-pathology','hospital-qbj','PATHOLOGY','病理科','[]','第一住院楼 2F','','病理科成立于2000年，为成都市青白江区病理质量控制中心。','病理科成立于2000年，为成都市青白江区病理质量控制中心。 主要设备：全自动组织脱水机，石蜡切片机，自动包埋机，高档进口显微镜，图像分析系统和图文报告系统，冰冻切片机，HE染封一体机，全自动免疫组织化学染色机等。 业务范围：常规组织病理诊断，液基薄层细胞学，普通细胞学，术中冰冻切片诊断，特殊染色技术，免疫组织化学技术。 特色技术：宫颈液基细胞学检查、免疫组织化学 科室咨询电话：028-89339410 科室地点：第一住院楼2楼','active',5,'2026-08-28T00:00:00+08:00'),
('dept-qbj-transfusion','hospital-qbj','TRANSFUSION','输血科','[]','第一住院楼 2F','','输血科成立于2014年5月，承担青白江区储血点的工作；与青白江区5家医疗机构签订供血协议，保障青白江区的血液制品供应并提供血液输注相关技术指导。科室按照三级医院输血科配置要求布局建设，拥有完善的管理制度及管理体系。','输血科成立于2014年5月，承担青白江区储血点的工作；与青白江区5家医疗机构签订供血协议，保障青白江区的血液制品供应并提供血液输注相关技术指导。科室按照三级医院输血科配置要求布局建设，拥有完善的管理制度及管理体系。 主要设备：医用储血冰箱，医用储血冰柜，循环解冻溶浆机，血小板恒温保存箱，全自动血型鉴定仪，FYQ试剂卡孵育器，TB-3A低速离心机，显微镜，ZRI-I热合机。 业务范围：血型鉴定，血型单特异性抗体鉴定，特殊介质交叉配血，直…','active',6,'2026-08-28T00:00:00+08:00'),
('dept-qbj-anesthesia','hospital-qbj','ANESTHESIA','麻醉科','[]','第一住院楼 2F','手术部','麻醉科手术室目前有9个现代化层流手术间（其中百级手术间2间、万级手术间7间、负压手术间1间）及按标准配备的麻醉恢复室。每个手术间均安装有标准的中心供氧、中心吸引、废气排出系统、高级无影灯、多功能外科吊塔，均配备有先进的手术床、进口麻醉机、多参数监护仪；有先进的微量输注泵、术中体温保温设备、手术麻醉信息系统、高频电刀、超声刀、腹腔镜、除颤仪等仪器设备。','麻醉科手术室目前有9个现代化层流手术间（其中百级手术间2间、万级手术间7间、负压手术间1间）及按标准配备的麻醉恢复室。每个手术间均安装有标准的中心供氧、中心吸引、废气排出系统、高级无影灯、多功能外科吊塔，均配备有先进的手术床、进口麻醉机、多参数监护仪；有先进的微量输注泵、术中体温保温设备、手术麻醉信息系统、高频电刀、超声刀、腹腔镜、除颤仪等仪器设备。 麻醉科手术室承担着全院的手术麻醉、手术配合工作及手术室外的舒适化诊疗麻醉工作，一年完…','active',7,'2026-08-28T00:00:00+08:00'),
('dept-qbj-emergency','hospital-qbj','EMERGENCY','急诊医学科','[]','门诊楼 1F','急诊区','急诊医学科建筑面积1600平方米，按照现代急诊急救布局设置规范，设有复苏抢救室、胸痛卒中处置区、急诊监护室、急诊观察室、急诊内科诊断室、急诊外科诊断室、换药室、注射室、洗胃室、清创室、犬伤处置室等功能区，拥有有创/无创呼吸机、转运呼吸机、除颤仪、心电监护仪、铲式担架、脊柱板、心肺复苏机、可视喉镜、全自动洗胃机、床旁快速检测等急救设备。','急诊医学科建筑面积1600平方米，按照现代急诊急救布局设置规范，设有复苏抢救室、胸痛卒中处置区、急诊监护室、急诊观察室、急诊内科诊断室、急诊外科诊断室、换药室、注射室、洗胃室、清创室、犬伤处置室等功能区，拥有有创/无创呼吸机、转运呼吸机、除颤仪、心电监护仪、铲式担架、脊柱板、心肺复苏机、可视喉镜、全自动洗胃机、床旁快速检测等急救设备。 急诊医学科包括院前急救及院内急诊两部分，分为内科和外科两个专业,承担全区急危重症的急诊、急救工作。院…','active',8,'2026-08-28T00:00:00+08:00')
INSERT INTO departments (id,hospital_id,code,name,aliases,floor,zone,description,specialty,status,sort_order,updated_at) VALUES
('dept-qbj-infectious','hospital-qbj','INFECTIOUS','感染性疾病科','[]','门诊楼 1F','发热门诊','感染性疾病科2015年9月成立，科室设置相对独立，面积800平方米，内部结构布局合理，分区清楚。设置有独立的发热、腹泻、结核、肝炎门诊和儿科发热门诊。病区设有独立的诊室、候诊区、隔离观察室、处置室、抢救室、卫生间、挂号收费室及药房，发热隔离病房设床位12张，含2张抢救床。','感染性疾病科2015年9月成立，科室设置相对独立，面积800平方米，内部结构布局合理，分区清楚。设置有独立的发热、腹泻、结核、肝炎门诊和儿科发热门诊。病区设有独立的诊室、候诊区、隔离观察室、处置室、抢救室、卫生间、挂号收费室及药房，发热隔离病房设床位12张，含2张抢救床。 科室现有医生7人，护理人员6人，其中高级职称2人，中级职称3人，初级职称7人，人员配置及梯队结构合理。其中科主任和护士长均有呼吸科多年临床工作经验。 科室配备心电监…','active',9,'2026-08-28T00:00:00+08:00'),
('dept-qbj-pharmacy','hospital-qbj','PHARMACY','药剂科','[]','门诊楼 1F','门诊药房','药剂科有药学技术人员34名，其中主任药师一名，副主任药师2名；药学研究生3名。下设药品库房、门诊药房、中药房、住院药房。','药剂科有药学技术人员34名，其中主任药师一名，副主任药师2名；药学研究生3名。下设药品库房、门诊药房、中药房、住院药房。 医院重视药剂科发展，对药剂科硬件、软件系统不断升级改造。中药房开展“智慧药房”中药饮片代煎配送服务，中药汤剂免费配送到家；门诊西药房增设前置处方审核系统；住院药房增加口服药品自动包药机；药品库房启用冷链药品监控系统，对库房温度、湿度进行实时监测和记录，发送报警信息通知相关人员，完善合理用药支持系统，为医务人员提供实…','active',10,'2026-08-28T00:00:00+08:00'),
('dept-qbj-picc','hospital-qbj','PICC','PICC门诊','[]','门诊楼 2F','205','PICC适用于需要中长期静脉治疗，特别是多疗程化疗及肠外营养支持的患者，可减少病人反复穿刺的痛苦，保护外周血管，并发症少、维护简便，提高病人的生活质量。我院已能成熟开展PICC置管技术，导管维护1万余人次。','PICC适用于需要中长期静脉治疗，特别是多疗程化疗及肠外营养支持的患者，可减少病人反复穿刺的痛苦，保护外周血管，并发症少、维护简便，提高病人的生活质量。我院已能成熟开展PICC置管技术，导管维护1万余人次。 PICC门诊主要业务： 1.PICC导管的留置及置管后健康宣教。 2.PICC导管的日常维护。 3.PICC导管常见问题处理。 4.医院PICC质量监控。','active',11,'2026-08-28T00:00:00+08:00'),
('dept-qbj-tcm','hospital-qbj','TCM','中医科','[]','门诊楼 2F','中医馆','中医科是集传统中医特色与现代先进中医药治疗技术于一体的大型综合性科室。科室主要治疗中医骨伤科、针灸科、推拿科、中医内妇儿外常见病多发病。开展颈椎间盘突出症、腰椎间盘突出症、各部位骨质增生、网球肘、肩周炎、面瘫、各部位骨性关节炎、早期股骨头缺血性坏死、各种肌肉劳损、各类软组织损伤，闭合性骨折脱位的手法复位、中医内妇儿外及各类杂证的治疗，以及各类亚健康人群调理。采用牵引、手法推拿复位、电针、艾灸、拔罐、中药蒸汽浴治疗、穴位注射、火针、浮针、超微针刀、放血疗法、中药外敷、中药内服等综合治疗。专业特色：中药蒸汽浴特色治疗、外敷中药特色治疗、中医治未病、超微针刀疗法、小儿推拿等。','外敷中药治疗、超微针刀疗法、中医治未病、小儿推拿','active',12,'2026-08-28T00:00:00+08:00'),
('dept-qbj-nutrition','hospital-qbj','NUTRITION','临床营养科','[]','门诊楼 2F','营养咨询门诊','临床营养科于2014年3月成立。科室开展营养筛查、营养评估、营养宣教，并参与临床会诊，为糖尿病、高血压、肠道疾病、围手术期病员及危重病人提供肠内营养支持治疗。负责对亚健康人群、慢性疾病（如糖尿病、高血压、冠心病）患者、特殊人群（孕妇、儿童、老年人）进行营养咨询，制定个性化、合理化的营养指导及治疗方案。科室定期向临床医护人群、病员及家属、社区居民进行营养与健康知识讲座，坚持为广大居民群众宣传健康膳食知识，提供科学合理的饮食指导。开设营养咨询门诊，出诊时间：周二下午。','临床营养科于2014年3月成立。科室开展营养筛查、营养评估、营养宣教，并参与临床会诊，为糖尿病、高血压、肠道疾病、围手术期病员及危重病人提供肠内营养支持治疗。负责对亚健康人群、慢性疾病（如糖尿病、高血压、冠心病）患者、特殊人群（孕妇、儿童、老年人）进行营养咨询，制定个性化、合理化的营养指导及治疗方案。科室定期向临床医护人群、病员及家属、社区居民进行营养与健康知识讲座，坚持为广大居民群众宣传健康膳食知识，提供科学合理的饮食指导。开设营养…','active',13,'2026-08-28T00:00:00+08:00'),
('dept-qbj-wound','hospital-qbj','WOUND','伤口造口门诊','[]','门诊楼 2F','207','伤口造口专科门诊开设于2014年，采用先进的治疗理念，为患者提供伤口造口的护理及治疗。','伤口造口专科门诊开设于2014年，采用先进的治疗理念，为患者提供伤口造口的护理及治疗。 目前已成熟开展以下业务： 1.伤口护理：各类急性伤口及慢性伤口（压疮、糖尿病足、溃疡、烧烫伤、失禁性皮炎、术后难愈伤口）的护理。 2.造口护理：各类造口术前及术后护理、造口用品的使用指导（肠道造口、膀胱造瘘）。','active',14,'2026-08-28T00:00:00+08:00'),
('dept-qbj-ped','hospital-qbj','PED','儿科','[]','门诊楼 2F','儿科区','儿科是青白江区优势学科，是集儿童医疗、保健、科研教学为一体的成建制儿童专科，科室除长期开展儿童保健，儿童常见病、多发病的诊治外，对儿童疑难病症、危急重症的治疗、抢救具有丰富的成功经验。专业特色：儿科新生儿室条件优越，符合院感流程及要求，为新生儿疾病的诊治提供有力的硬件保障；儿童保健及生长指导。','新生儿危急重症救治、儿童支气管哮喘及慢性咳嗽的诊治、儿童保健及生长指导','active',15,'2026-08-28T00:00:00+08:00'),
('dept-qbj-lab','hospital-qbj','LAB','医学检验科','[]','门诊楼 2F','静脉采血室','医学检验科是青白江区检验专业教学科研中心，也是全区输血管理和临床检验质量控制中心。','医学检验科是青白江区检验专业教学科研中心，也是全区输血管理和临床检验质量控制中心。 主要设备：血细胞分析仪流水线；全自动尿液分析仪流水线；全自动血凝分析仪；全自动细菌培养药敏分析系统；全自动生化分析流水线；全自动化学发光免疫分析流水线；全自动糖化血红蛋白检测仪。 业务范围：肝功能、肾功能、电解质、血糖、血脂、心肌酶、C-反应蛋白及超敏C-反应蛋白、尿液、血液、体液等常规项目检测、细菌培养。 特色技术：各种肝炎病毒抗体、细菌及病毒病原体…','active',16,'2026-08-28T00:00:00+08:00')
INSERT INTO departments (id,hospital_id,code,name,aliases,floor,zone,description,specialty,status,sort_order,updated_at) VALUES
('dept-qbj-stomatology','hospital-qbj','STOMATOLOGY','口腔科','[]','门诊楼 2F','具体诊室以当日排班为准','口腔科拥有丰富的口腔医疗技术资源，能开展口腔种植技术、口腔粘膜病的系统诊治、无痛微创拔牙技术、活动翼矫治牙列不齐等牙颌面畸形、全瓷冠桥修复、牙科X光CR读片系统等。临床开展的亚专业有牙体牙髓科、牙周科、牙槽外科、口腔颌面外科、口腔修复、口腔正畸等。专业特色：埋伏阻生牙拔除术、烤瓷贴面技术、牙种植技术。','烤瓷贴面技术、牙种植技术','active',17,'2026-08-28T00:00:00+08:00'),
('dept-qbj-obgyn','hospital-qbj','OBGYN','妇产科','[]','门诊楼 2F','妇产科区','妇产科是全区孕产妇保健、分娩中心，妇产科疾病诊治及产科急救中心，建立有高危妊娠规范化管理和诊疗系统，和院内重症医学科、麻醉科、输血科、介入肿瘤科、内分泌及肾病内科等组建了MDT急救团队，承接区内和周边地区各种高危孕产妇的救治，对严重产后出血、妊娠期高血压疾病、妊娠合并严重的内外科疾病等危重症抢救有丰富的临床经验。现已发展为全区领先水平的集医疗、教学、科研、保健、康复为一体的现代化科室。2019年7月与四川省科学院·四川省人民医院建立生殖专科联盟医院并增设了生殖内分泌与不孕专科门诊，2021年与四川大学华西第二医院建立盆底疾病专病联盟。近年来，微创手术逐步取代传统手术，我科在成功开展阴式系列手术，经腹腔镜、冷刀宫腔镜手术的基础上，于2019年率先在区内开展了单孔腹腔镜手术。','经脐单孔腹腔镜微创手术、冷刀宫腔镜手术、椎管内麻醉的镇痛分娩、盆底功能康复','active',18,'2026-08-28T00:00:00+08:00'),
('dept-qbj-rehab','hospital-qbj','REHAB','康复医学科','[]','门诊楼 2F','外科区','康复医学科是成都市医学重点专科建设项目，青白江区医疗康复定点医疗机构，青白江区工伤急性期康复定点医疗机构。以现代康复医学理论及康复治疗技术，结合中医传统康复为诊疗特色的临床专科。科室常规开展康复评定、运动治疗、作业治疗、物理因子治疗、言语吞咽治疗、中医康复治疗、康复工程等一系列康复技术。','神经调控技术、核心肌力稳定性训练技术、骨科术后快速康复（ERAS）、烧伤康复治疗技术、吞咽障碍康复技术','active',19,'2026-08-28T00:00:00+08:00'),
('dept-qbj-nursing','hospital-qbj','NURSING','护理组','[]','门诊楼 2F','PICC/伤口造口门诊','院方医生资料中已收录护理组专家与出诊信息。','具体诊疗范围以院方当日门诊安排和现场分诊为准。','active',20,'2026-08-28T00:00:00+08:00'),
('dept-qbj-urology','hospital-qbj','UROLOGY','泌尿外科','[]','门诊楼 2F','外科区','泌尿外科是成都市医学重点专科建设项目，在成都市北部片区具有较强影响力，以泌尿系统结石、膀胱肿瘤、前列腺疾病为临床和科研特色，近年来，已全面开展泌尿外科相关技术项目，涵盖了几乎所有的病种，科室微创手术率达90%，几乎取代传统开放手术。科室主任、学科带头人贾其磊主任医师为泌尿外科专业博士，从事临床工作20余年，擅长前列腺疾病、泌尿系结石、尿道修复重建、泌尿系畸形等疾病的治疗，近年来在国内外医学杂志上发表论文10余篇（含SCI论文），获市级科技进步奖1项，承担厅、市级科研课题3项，曾在意大利UNIVERSITÀ DEGLI STUDI DI SALERNO研修三个月。技术名称：根治性膀胱全切+尿流改道术','根治性膀胱全切+尿流改道术、经尿道前列腺剜除术、经腹腔镜肾部分切除术、腔道内泌尿系结石手术','active',21,'2026-08-28T00:00:00+08:00'),
('dept-qbj-breast-thoracic','hospital-qbj','BREAST_THORACIC','甲乳胸外科','["甲乳外科", "乳腺外科"]','门诊楼 2F','外科区','甲乳胸外科是以甲状腺、乳腺、胸外科为专业特色的科室。科室拥有乳腺钼靶、乳腺微创旋切机、移动查房车、胸腔镜及超声刀等先进设备。科室医护团队专业、成熟，主要承担甲状腺、乳腺、胸外方面的疾病救治，对乳房整形、乳腺良恶性肿瘤、甲状腺结节、甲状腺癌、肺结节、肺癌、食管癌、胸部外伤等疾病诊治具有丰富的临床经验。','乳腺癌诊断及系统、个体化、精准治疗、经皮乳腺肿物切除术、胸腔镜（VATS）下肺叶及亚肺叶、肺大疱切除术，胸腹腔镜下食管癌及食管胃交界癌、膈疝手术','active',22,'2026-08-28T00:00:00+08:00'),
('dept-qbj-pain','hospital-qbj','PAIN','疼痛科','[]','门诊楼 2F','中医馆','疼痛科是青白江区率先开设的疼痛疾病治疗专科，在成都市北部片区具有较强影响力。科室开展针对疼痛的各种保守治疗、神经阻滞治疗以及采用各种疼痛介入疗法治疗颈、腰椎间盘突出症，颈、腰椎病，带状疱疹后神经痛，三叉神经痛，手术后疼痛等多种临床常见慢性疼痛及复杂顽固性疼痛。专业特色：臭氧相关治疗；微创介入术。','神经阻滞治疗、靶点导向低温等离子颈、腰椎间盘髓核减压技术、臭氧治疗、射频脉冲热凝技术','active',23,'2026-08-28T00:00:00+08:00'),
('dept-qbj-ent-ophth','hospital-qbj','ENT_OPHTH','眼科及耳鼻咽喉科','["眼科", "耳鼻咽喉科", "五官科"]','门诊楼 2F','五官科区','眼科及耳鼻咽喉科是诊治眼、耳、鼻、喉科常见病、多发病、疑难病的专业科室，开展或协作开展眼耳鼻喉及口腔科常规手术及部分高难度手术。开展睡眠呼吸监测(鼾症)、白内障(超声乳化技术)、低温等离子技术等特色技术。','白内障超声乳化+人工晶体植入术、耳鼻喉内窥镜手术','active',24,'2026-08-28T00:00:00+08:00')
INSERT INTO departments (id,hospital_id,code,name,aliases,floor,zone,description,specialty,status,sort_order,updated_at) VALUES
('dept-qbj-neurosurgery','hospital-qbj','NEUROSURGERY','神经外科','["神外科"]','门诊楼 2F','外科区','神经外科是青白江区优势专科，建有神经外科重症监护室。常规开展颅脑脊柱脊髓损伤综合救治，脑血管病诊治，神经系统肿瘤诊治，周围神经系统疾病诊治等业务。专业特色：重型颅脑损伤救治（包括手术）、高血压脑出血手术治疗、脑血管病诊治（颅内动脉瘤开颅夹闭手术、颅内动脉瘤血管内栓塞术、颅内动静脉畸形切除术、颈内动脉狭窄内膜剥脱术等）、颅内椎管内肿瘤切除术、脊柱椎间盘脱出等退行性病变的手术治疗等。','颅内动脉瘤开颅夹闭手术、颅内血管畸形治疗、颅内肿瘤治疗、垂体瘤经蝶微创手术治疗、前路颈椎间盘切除减压植骨融合术（ACDF）','active',25,'2026-08-28T00:00:00+08:00'),
('dept-qbj-anorectal','hospital-qbj','ANORECTAL','肛肠科','[]','门诊楼 2F','中医馆','肛肠科是医院极具特色的中西医结合专科，在肛肠疾病诊疗方面，采用中药熏洗、内服、外敷、结扎、挂线等中医药传统疗法，结合现代诊疗技术，形成一套完善的特色诊疗体系。','医师1名，其中硕士研究生2名','active',26,'2026-08-28T00:00:00+08:00'),
('dept-qbj-gi-surgery','hospital-qbj','GI_SURGERY','胃肠肝胆外科','["普外科", "普通外科"]','门诊楼 2F','外科区','普外科是以胃肠、疝、肝、胆、胰、脾、烧伤为专业特色的科室。开展腹腔镜结、直肠癌根治术，规范化胃癌标准根治术，腹腔镜胆囊、阑尾、疝修补术，双镜联合胆道取石术，MDT（多学科参与）肝癌规范化治疗，半肝切除术，肝门胆管癌根治术，腔镜下肝血管瘤剥除术，胆总管先天性囊肿切除术，胰十二指肠切除术，肝脾破裂手术，还开展日间手术、加速康复外科，极大缩短住院时间，深受患者好评。','腹腔镜结、直肠癌根治术、开放及腔镜肝切除术、慢性溃疡创面的治疗','active',27,'2026-08-28T00:00:00+08:00'),
('dept-qbj-thoracic','hospital-qbj','THORACIC','胸外科','[]','门诊楼 2F','外科区','我院胸外科是四川省基层医院微创胸外科能力提升项目建设单位，通过华西医院专家的指导及技术下沉，我院胸外科专业团队独立开展了大量新业务、新技术，如全胸腔镜下肺叶、肺段切除术，CT引导下肺结节定位病损切除术，胸廓畸形矫正手术，利用3D打印技术行胸壁病损切除及重建手术等，并开展了领先的诊疗模式--肺结节MDT（多学科联合会诊）。','医师1人，住院医师2人，其中，研究生1人，本科3人','active',28,'2026-08-28T00:00:00+08:00'),
('dept-qbj-ortho','hospital-qbj','ORTHO','骨科','[]','门诊楼 2F','外科区','骨科以创伤骨科、脊柱外科、关节外科、胸外科、运动医学为临床和科研特色，是青白江区优势学科。近年来，运动医学及脊柱内镜等微创新技术在骨科得到迅猛发展，各类疑难及重大手术剧增，例如关节镜下前后交叉韧带重建术、关节镜下腘窝囊肿切除术，脊柱内镜（UBE及椎间孔镜）下微创椎间盘切除术、椎管成形术、椎间融合、经皮置钉内固定术，颈椎寰枢关节骨折脱位切开复位内固定术，PKP（后路经皮球囊扩张椎体成形术），DAA（直接前方入路）微创全髋关节置换术，复杂髋膝关节置换及翻修术，全腔镜下食管癌根治术、肺癌根治术、纵膈占位切除、膈疝修补、食管胃交界癌根治术、心包手术、肺大疱切除等。专业特色：创伤、脊柱、关节、胸外、运动医学各亚专业医疗水平齐头并进的同时继续向微创化及复杂性手术深入发展。','UBE（单侧双通道脊柱内镜技术）、椎间孔镜技术、关节镜技术、DAA（直接前方入路）微创全髋关节置换术','active',29,'2026-08-28T00:00:00+08:00'),
('dept-qbj-psych','hospital-qbj','PSYCH','临床心理门诊','["心理咨询", "心身睡眠", "精神科门诊"]','门诊楼 3F','335','我院心身睡眠医学科主要为受情绪困扰、睡眠障碍困扰、身体莫名不适等患者和家属提供帮助。目前开展门诊有心身睡眠门诊和心理咨询门诊。采用药物治疗结合心理治疗的生物-医学-社会医疗模式。','我院心身睡眠医学科主要为受情绪困扰、睡眠障碍困扰、身体莫名不适等患者和家属提供帮助。目前开展门诊有心身睡眠门诊和心理咨询门诊。采用药物治疗结合心理治疗的生物-医学-社会医疗模式。 科室业务范围：抑郁症、焦虑症、睡眠障碍、心身疾病、躯体化障碍，植物神经功能紊乱、更年期综合征、肠易激综合征，以及慢性疾病所带来的负面情绪：焦虑、恐惧、害怕、失眠、抑郁、头昏、心慌等及特别的行为问题：自杀、成瘾等。','active',30,'2026-08-28T00:00:00+08:00'),
('dept-qbj-clinical-pharmacy','hospital-qbj','CLINICAL_PHARMACY','临床药学科','[]','门诊楼 3F','321 用药咨询门诊','临床药学科成立于2016年4月，科室从事全院药事管理、临床合理用药、抗菌药物应用管理、门急诊处方点评、住院医嘱审核、药学查房、不良反应监测及上报、药学监护、用药咨询、用药重整、慢病管理、临床疑难病例讨论、临床会诊、大专院校实习生带教及其他药学工作。','临床药学科成立于2016年4月，科室从事全院药事管理、临床合理用药、抗菌药物应用管理、门急诊处方点评、住院医嘱审核、药学查房、不良反应监测及上报、药学监护、用药咨询、用药重整、慢病管理、临床疑难病例讨论、临床会诊、大专院校实习生带教及其他药学工作。 主要业务： 1.用药咨询门诊 每周一至周五都有经验丰富的药师免费为门诊患者及医护解答临床用药问题，包括特殊人群用药、特殊剂型药品使用方法、检查相关药物使用方法及注意事项、高危药品使用注意事…','active',31,'2026-08-28T00:00:00+08:00'),
('dept-qbj-weight-mgmt','hospital-qbj','WEIGHT_MGMT','体重管理门诊','[]','门诊楼 3F','309','院方医生资料中已收录体重管理门诊专家与出诊信息。','具体诊疗范围以院方当日门诊安排和现场分诊为准。','active',32,'2026-08-28T00:00:00+08:00')
INSERT INTO departments (id,hospital_id,code,name,aliases,floor,zone,description,specialty,status,sort_order,updated_at) VALUES
('dept-qbj-health-mgmt','hospital-qbj','HEALTH_MGMT','健康管理门诊','[]','门诊楼 3F','体检中心','院方医生资料中已收录健康管理门诊专家与出诊信息。','具体诊疗范围以院方当日门诊安排和现场分诊为准。','active',33,'2026-08-28T00:00:00+08:00'),
('dept-qbj-child-health','hospital-qbj','CHILD_HEALTH','儿童保健科','["儿保科", "儿保室"]','门诊楼 3F','儿保/特需门诊区','儿童保健科简称儿保科，是集儿童生长发育，儿童保健诊疗，婴幼儿及儿童心理发育评估，婴幼儿营养与喂养于一体的临床一级专业科室，常年接收0～5岁儿童的系统儿童保健的建卡检查即儿童生长发育工作，以及散居儿童的儿保工作。科室致力于保障和促进儿童身心健康及儿童生长发育的各项临床工作。儿童保健学科包括了儿童临床医学、儿童教育学、儿童心理学、儿童营养学等多方面学科。','儿童保健科简称儿保科，是集儿童生长发育，儿童保健诊疗，婴幼儿及儿童心理发育评估，婴幼儿营养与喂养于一体的临床一级专业科室，常年接收0～5岁儿童的系统儿童保健的建卡检查即儿童生长发育工作，以及散居儿童的儿保工作。科室致力于保障和促进儿童身心健康及儿童生长发育的各项临床工作。儿童保健学科包括了儿童临床医学、儿童教育学、儿童心理学、儿童营养学等多方面学科。 儿保科各门诊开展的具体业务 1、儿童生长发育体检门诊：通过体检，定期的生长监测可以评…','active',34,'2026-08-28T00:00:00+08:00'),
('dept-qbj-endo-neph','hospital-qbj','ENDO_NEPH','内分泌及肾病内科','["内分泌科", "肾病内科", "肾内科"]','门诊楼 3F','内科区','内分泌及肾病内科设有门诊、住院部和血液透析室。科室在内分泌系统及肾内科疾病的诊治方面，如糖尿病及其并发症、骨质疏松的诊治方面有丰富的临床经验，能开展肾上腺疾病、甲状腺疾病、垂体疾病、内分泌性高血压、肥胖、脂代谢异常、骨软化、多囊卵巢综合征、痛风及水、电解质紊乱的诊治、尿路感染、肾小管酸中毒、慢性肾脏疾病、慢性肾功能衰竭的诊治和血液透析治疗等。专业特色：血液透析技术、四肢多普勒血流图测定、胰岛素泵治疗、带隧道带涤纶套血透导管置入术、肾穿刺活检术、经皮腔内血管成形术等。','带隧道带涤纶套血透导管置入术、四肢多普勒血流图测定、肾穿刺活检术、经皮腔内血管成形术（PTA）','active',35,'2026-08-28T00:00:00+08:00'),
('dept-qbj-aesthetic','hospital-qbj','AESTHETIC','医疗美容科','[]','门诊楼 3F','皮肤科诊区','医疗美容科门诊开展业务：','医疗美容科门诊开展业务： 1.眼部整形美容：重睑术(双眼皮)、眼袋矫正术、上睑下垂、内眦赘皮矫正术、小眼开大术、败眉切除术、抬眉术、各种眼外伤整形修复术等。 2.鼻部整形美容：隆鼻术、鼻综合(耳软骨、肋软骨)、驼峰鼻矫正术、鹰勾鼻矫正术、鼻缺损修复等。 3.乳房整形美容：副乳房切除的整形技术，男性发育乳房切除的整形技术， 腋窝部的美容隐蔽切口手术技术，隆胸和再造乳房植入假体的取出、隐蔽性切口注射隆胸注射剂， 乳头缩小术、乳晕缩小术，隆…','active',36,'2026-08-28T00:00:00+08:00'),
('dept-qbj-resp','hospital-qbj','RESP','呼吸与危重症医学科','["呼吸内科"]','门诊楼 3F','呼吸内科区','呼吸与危重症医学科开展急慢性呼吸道感染性疾病、气道阻塞性疾病、肺源性心脏病、呼吸衰竭、胸膜性疾病、呼吸系统肿瘤等疾病诊断治疗，肺功能检查、无创正压通气、电子支气管镜检查及治疗、呼吸内镜介入治疗（经气管镜球囊扩张治疗、经气管镜气道支架置入术、经气管镜球囊探查联合自体血难治性气胸封堵术等）、CT引导下经皮肺穿刺、胸膜活检。专业特色：气道良恶性病变的微创治疗、支气管肺泡灌洗、气道异物取出等。','镇静镇痛支气管镜检查、无创呼吸机、肺功能检查','active',37,'2026-08-28T00:00:00+08:00'),
('dept-qbj-resp-chronic','hospital-qbj','RESP_CHRONIC','呼吸慢病门诊','[]','门诊楼 3F','330','院方医生资料中已收录呼吸慢病门诊专家与出诊信息。','具体诊疗范围以院方当日门诊安排和现场分诊为准。','active',38,'2026-08-28T00:00:00+08:00'),
('dept-qbj-card','hospital-qbj','CARD','心血管内科','["心内科"]','门诊楼 3F','心血管内科区','心血管内科是成都市医学重点专科，正在申报省级重点专科，在成都市北部片区具有较强影响力，分为A区和B区。科室与成都市第二人民医院心内科深度合作，开展心内科领域全部介入手术。专业特色：冠状动脉造影及经皮冠脉内支架植入术（包括：急性心肌梗死急诊PCI术、血栓抽吸术、分叉病变及左主干病变PCI术、冠状动脉慢性闭塞性病变（CTO）支架置入术）、主动脉内球囊反搏术、冠状动脉血管内超声（IVUS）、心脏电生理检查及三维指导下复杂心律失常射频消融术、心脏临时及永久起搏器植入术、心脏希氏束起搏、埋藏式心脏自动复律除颤器植入术（ICD）等。','心脏电生理检查及射频消融术、冠状动脉造影及支架植入术、冠状动脉血管内超声、心脏起搏器植入术','active',39,'2026-08-28T00:00:00+08:00'),
('dept-qbj-gastro','hospital-qbj','GASTRO','消化内科','[]','门诊楼 3F','内科区','消化内科是青白江区优势专科，科室设有门诊、病区和内窥镜室。开展胃食道反流、急慢性胃炎、消化性溃疡、消化道出血、胰腺炎、胃肠道肿瘤、炎症性肠病、肠结核、结核性腹膜炎、功能性胃肠疾病；乙肝、丙肝、肝硬化失代偿期、酒精性肝炎、自身免疫性肝炎等疾病诊疗。内窥镜室开展常规胃镜、肠镜检查，无痛胃镜、肠镜检查及内镜下治疗。专业特色：肝病治疗；内镜下治疗。','超声内镜、放大内镜、食管静脉曲张套扎术、内镜下组织胶注射治疗胃底静脉曲张、EMR（内镜粘膜切除术）以及ESD（内镜粘膜下剥离术）','active',40,'2026-08-28T00:00:00+08:00')
INSERT INTO departments (id,hospital_id,code,name,aliases,floor,zone,description,specialty,status,sort_order,updated_at) VALUES
('dept-qbj-derm','hospital-qbj','DERM','皮肤科','[]','门诊楼 3F','皮肤科诊区','皮肤科是成都市医学重点专科，是成都市第二人民医院皮肤科直接指导科室。是青白江区皮肤病性病治疗控制分中心、艾滋病治疗质控分中心。科室除开展常见皮肤病与性病诊治外，还率先在区域内开展皮肤外科、皮肤美容等技术，拥有强脉冲光治疗仪、Q开关ND：YAG激光治疗仪、超脉冲二氧化碳点阵激光治疗仪、308准分子光治疗仪等各种高端治疗仪器。电子皮肤镜检查、皮肤活检术、果酸活肤术、308准分子光相关治疗、超脉冲点阵激光相关治疗、调Q激光相关治疗及光子嫩肤术为科室特色治疗项目。','电子皮肤镜检查、308准分子光治疗白癜风、光电美容治疗','active',41,'2026-08-28T00:00:00+08:00'),
('dept-qbj-neuro','hospital-qbj','NEURO','神经内科','["神内科"]','门诊楼 3F','内科区','神经内科是青白江区领衔专科，开展脑梗塞、脑出血、短暂性脑缺血发作、癫痫、眩晕、偏头痛、各类脑炎、脊髓炎、重症肌无力、格林-巴利综合征、面瘫、多发性硬化、帕金森、痴呆、多系统萎缩、睡眠障碍、焦虑抑郁、脑动脉供血不足等疾病诊治。专业特色：脑血管病的预防、急救（急性脑梗塞的静脉溶栓治疗）、康复；帕金森病、癫痫、神经肌肉病、头面痛、神经系统感染性疾病的诊断与治疗。','脑电图、动态脑电图检查、脑功能障碍治疗仪、肌电图、神经电图、诱发电位检查、急性脑梗死静脉溶栓治疗、全脑血管造影术、脑动脉取栓术','active',42,'2026-08-28T00:00:00+08:00'),
('dept-qbj-radiotherapy','hospital-qbj','RADIOTHERAPY','肿瘤放疗科','[]','门诊楼 3F','320','肿瘤放疗科是专业从事肿瘤规范化诊断及治疗的临床科室，是青白江区集肿瘤预防、诊断、治疗及康复为一体的特色专科，在成都市北部片区具有较强影响力。科室承担成都市重特大疾病认定及治疗工作，是青白江区癌症防治中心、肿瘤性疾病质控中心及临终关怀质量控制中心。专业特色：肿瘤性疾病的筛查、诊断；恶性肿瘤化疗、靶向治疗、免疫治疗等；PCA镇痛技术；肿瘤深部热疗；PICC/CVC置管、输液港植入及维护。','肿瘤化疗、靶向治疗、免疫治疗、肿瘤深部热疗、癌痛规范化治疗、肿瘤营养支持治疗及安宁疗护','active',43,'2026-08-28T00:00:00+08:00'),
('dept-qbj-intervention','hospital-qbj','INTERVENTION','肿瘤血管介入科','[]','门诊楼 3F','319','肿瘤血管介入科现有医护人员17名，床位33张，现有型号Innova3100 DSA 一台、高压注射器一台、除颤监护仪一台、呼吸机一台、穿刺活检枪一支、心电监护仪微量注射泵等各种设备。建科以来，科室坚持综合性治疗及个体化治疗相结合的原则，以“病人为中心”，开展多学科诊疗协作，精准治疗，提高患者生存期。目前是“青白江区外周介入质控中心”、“癌痛规范化诊疗培育单位”，并于2019年被授予“全国难治性癌痛规范化诊疗基地”。','肿瘤血管介入科现有医护人员17名，床位33张，现有型号Innova3100 DSA 一台、高压注射器一台、除颤监护仪一台、呼吸机一台、穿刺活检枪一支、心电监护仪微量注射泵等各种设备。建科以来，科室坚持综合性治疗及个体化治疗相结合的原则，以“病人为中心”，开展多学科诊疗协作，精准治疗，提高患者生存期。目前是“青白江区外周介入质控中心”、“癌痛规范化诊疗培育单位”，并于2019年被授予“全国难治性癌痛规范化诊疗基地”。 业务范围：肿瘤介入…','active',44,'2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-001','hospital-qbj','dept-qbj-tcm','QBJ-D001','张素英','科室主任、主任中医师','成都市第四批名中医，青白江区名中医，四川省中医药传承创新发展先进个人，成都市中医骨伤医疗质量控制中心专家，善于运用中医辨证论治理论体系和中医药特色诊疗方法，在诊治骨伤科常见病、疑难病、危急重症方面具有独特的诊疗技术专长，特别擅长颈、腰椎间盘突出手法推拿复位治疗。临床主要治疗各类跌打损伤、各种急慢性疼痛、颈椎病、腰椎间盘突出症、各部位骨质增生、骨性关节炎、网球肘、肩周炎、膝关节病、中风后遗症、面瘫等疾病。采用推拿、针灸、中药熏蒸、火针、拔罐、放血、超微小针刀、中药外敷等综合治疗，疗效显著。近年来对疑难病腰椎间盘脱出及脊髓型颈椎病的治疗取得良好效果。平时善于继承创新、勇于实践，潜心传承中医药学术，经过30余年的临床实践，创立了一套自己独特的推拿手法，自己研制的中药外敷新伤1号、陈伤2号、肿痛3号、中药熏蒸、中药烫熨等处方已广泛用于临床，疗效独特。有多篇论著及论文在中国科技核心期刊及医学杂志上发表。坐诊地点：成都市青白江区人民医院门诊二楼中医馆名中医 工作室','周二、周五上午；周三全天','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-002','hospital-qbj','dept-qbj-tcm','QBJ-D002','黎海军','科室副主任、副主任中医师','硕士学历，四川省中医药适宜技术研究会推拿分会委员，中国针灸学会会员，从事针灸推拿临床13年，曾在四川省中西医结合医院进修。擅长中医针灸、正骨推拿、中药内服外敷及康复评定等诊疗技术，如：筋针、阴阳九针、皇帝内针、电火针、超微针刀、浮针、B超引导下关节腔注射治疗、整脊等。主治中医骨伤（如：脊柱关节病、急慢性软组织损伤、稳定性骨折、青少年脊柱畸形及产后骨盆倾斜）、中医内科、皮肤科、亚健康（如植物神经功能紊乱、围绝经期综合征、睡眠障碍）等各科病种。发表SCI论文1篇，核心期刊2篇，统计源期刊论文及科普文多篇，承担成都市卫健委科研项目1项。','周一、周四上午；周五下午','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-003','hospital-qbj','dept-qbj-tcm','QBJ-D003','马军','副主任中医师','毕业于成都中医药大学中医学专业，医学学士，四川省针灸学会推拿分委会委员，四川省中医药适宜技术研究会会员，参与研究成都市卫健委课题1项，从事中医内科、中医骨伤科工作十余年，具有丰富临床工作经验，对颈腰椎疾病，膝关节类疾病、内科脾胃病等疾病诊治有独到见解，擅长运用正骨、推拿、针灸、阴阳九针、浮针、小针刀、火针、放血、拔罐及中药内服等内外结合治疗法治疗颈腰椎疾患、网球肘、膝关节病、急慢性软组织损伤、外伤骨折肿痛、内科脾胃病等疾病，疗效显著。','周一至周日轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-004','hospital-qbj','dept-qbj-tcm','QBJ-D004','曾玉玮','主治中医师','中国抗癌协会会员 四川省中医药学会小儿推拿专业委员会委员 成都中医药大学中医内科专业硕士，参与成都市第五批中医师承（中医肿瘤方向）。擅长中医药结合针灸等治疗成人和小儿的消化系统及呼吸系统常见病。现主要开展疾病有肿瘤放化疗、术后调理，肺结节、支气管炎、肺炎、慢阻肺、肺心病恢复期调理，消化不良、胃食管反流、肠易激综合征、急性胰腺炎及恢复期调理、不全性肠梗阻，各类型腹泻、腹胀，月经不调，盆腔炎，宫外孕。同时开展有儿科小儿推拿及穴位贴敷（止咳化痰贴 消胀贴 腹泻贴 三九、三伏贴）。','周一至周日轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-005','hospital-qbj','dept-qbj-tcm','QBJ-D005','王玫','主治中医师','毕业于成都中医药大学，本科学历，师从四川省中西医结合医院张凡教授。擅长治疗中医内科、儿科、妇科等常见病，尤其通过辨证施治对急性胰腺炎、肠梗阻、便秘、术后腹胀未排气及排便难等症治疗效果佳；针灸治疗呃逆、面瘫、面肌痉挛、失眠、中风、术后小便不通等常见病。开展了“三九贴”和“三伏贴”。','周一至周日轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-006','hospital-qbj','dept-qbj-tcm','QBJ-D006','张丽','主治中医师','毕业于成都中医药大学中医专业，从事中医临床康复工作近二十年，主要治疗中医骨伤科常见疾病，多发病。擅长运用针灸，推拿，中药饮片治疗颈腰椎间盘突出症，颈椎病，网球肘，膝关节骨性关节炎，肩周炎，中风后遗症，面瘫等疾病。有丰富的临床经验。','周一至周日轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-007','hospital-qbj','dept-qbj-tcm','QBJ-D007','刘增诚','主治中医师','毕业于成都中医药大学中医专业，从事中医临床工作十年，主要治疗中医骨伤科常见疾病，多发病。擅长运用针灸，推拿，中药饮片治疗颈腰椎间盘突出症，颈椎病，网球肘，膝关节骨性关节炎，肩周炎，中风后遗症，面瘫等疾病。有丰富的临床经验。','周一至周日轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-008','hospital-qbj','dept-qbj-tcm','QBJ-D008','杨文静','主治中医师','硕士研究生，毕业于成都市中医药大学针灸专业，曾于四川省中医院、华西医院中西医结合科学习。擅长中医骨伤科常见病，多发病。擅长运用针刺、艾灸、拔火罐、放血、刮痧、浮针、穴位埋线、穴位注射、埋针、中药、理疗等方面治疗疾病，擅长运用针灸治疗脑血管疾病、面瘫、落枕、失眠、痛经、颈、腰椎疾病、膝关节痛、肩关节痛、网球肘等临床疾病。','周一至周日轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-009','hospital-qbj','dept-qbj-tcm','QBJ-D009','李艳萍','主治中医师','硕士研究生，师承四川省名中医、四川大学华西医院一级专家唐文富教授，擅长冠心病、心悸、高血压、高脂血症、水肿、慢性稳定型心绞痛、眩晕、失眠多梦、咳嗽、慢性胃炎、口臭、月经不调、痛经、肿瘤等中医药治疗；善于运用针灸治疗颈椎病、肩周炎、腰肌劳损、腰椎间盘突出、膝关节炎、面瘫等；针灸美颜面部抗衰，调整面部轮廊和提升紧致度，改善面部浮肿暗黄、淡化法令纹、鱼尾纹、黄褐斑、调整大小脸等。','周一至周日轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-010','hospital-qbj','dept-qbj-tcm','QBJ-D010','黄康','中医师','毕业于成都中医药大学针灸推拿专业。从事中医临床工作10余年，擅长中医骨伤科常见病、多发病的诊治，尤其擅长运用针灸、推拿治疗劲腰椎间盘突出症、各种骨性关节炎、肩周炎、网球肘、中风后遗症、面瘫等。','周一至周日轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-011','hospital-qbj','dept-qbj-tcm','QBJ-D011','徐妙','中医师','先后毕业于成都中医药大学、天津中医药大学，硕士研究生。擅长中医药治疗内科疾病，对肺系、脾胃系疾病有自己的见解，调理亚健康状态。熟练掌握小儿推拿手法，通过手法为小儿保健，同时治疗小儿脾胃肺系等疾病。擅长针灸治疗中风后遗症，调节情绪与胃肠道疾病，缓解躯体疼痛。','周一至周日轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-012','hospital-qbj','dept-qbj-tcm','QBJ-D012','王琪','中医师','硕士研究生，先后毕业于湖南中医药大学、广州中医药大学针灸推拿学专业，参与广东省省部级课题1项，院内课题3项，发表SCI论文1篇，中文核心1篇。擅长运用浮针、颊针等治疗中风后遗症、面瘫、颈肩腰腿痛、网球肘、膝关节炎等疾病。','周一至周日轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-013','hospital-qbj','dept-qbj-pain','QBJ-D013','王伦','科室主任、副主任医师','中国中西医结合学会疼痛学专业委员会微创介入专家委员会 委员 中国中医药研究促进会红外疼痛医学分会 常务理事 四川省科技创新研究会难治性癌痛专业委员会 委员 四川省国际医学交流促进会骨质疏松骨病专业委员会 委员四川省医学传播学会骨骼运动系统损伤与疾病防治专业委员会委员 四川省医学会疼痛康复专业委员会 委员 四川省成都医学会疼痛专业委员会 委员 四川省成都市青白江区卫健委 优秀青年医师 毕业于四川大学华西临床医学专业，曾在成都市第二人民医院，绵阳科学城医院疼痛科进修学习。擅长应用各种神经阻滞的方法及微创介入方法治疗各种慢性腰腿痛，神经病理性疼痛以及癌痛等慢性疼痛疾患。疼痛介入疗法治疗颈、腰椎间盘突出症，颈、腰椎病，带状疱疹后神经痛，三叉神经痛，手术后疼痛及复杂顽固性疼痛等诊治方面具有丰富的临床经验。参与编定论著1部，发表论文4篇、科普文章6篇。','周一至周日轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-014','hospital-qbj','dept-qbj-pain','QBJ-D014','焦世华','市二医院专家、学科主任、副主任医师','中国中西医结合学会疼痛学专业委员会委员 四川省医创会难治性癌痛专委会委员 四川省国际医学交流促进会骨质疏松骨病专业委员会委员 从事疼痛临床诊疗工作三十多年，对各种疑难复杂的慢性疼痛的诊断、治疗具有丰富的临床经验，擅长运用各种神经阻滞、微创介入手术治疗三叉神经痛、颈腰椎间盘突出症、带状疱疹性神经痛、癌性疼痛及各种疑难复杂慢性疼痛疾病。','周一、周三全天','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-015','hospital-qbj','dept-qbj-pain','QBJ-D015','李琳','主治医师','从事临床工作近10年，曾于成都市第二人民医院疼痛科进修。擅长带状疱疹后遗神经痛、三叉神经痛、肋间神经痛、椎间盘突出腰腿痛、颈椎病引起的颈肩背上肢痛、肩周炎、网球肘、腱鞘炎、足跟痛、枕神经痛以及部分无名痛等顽痛的诊治。','周一至周日轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-016','hospital-qbj','dept-qbj-pain','QBJ-D016','顾文义','主治医师','从事临床工作10余年，先后于四川省科学城医院及北京宣武医院疼痛科进修学习。 擅长头痛、三叉神经痛、颈肩痛、腰腿痛、四肢关节疼痛、带状疱疹性神经痛、肌肉骨骼疼痛、神经病理性疼痛等多种慢性疼痛疾病的诊断及治疗。擅于应用现代疼痛医学手段治疗疼痛疾病，如:在超声引导下颈源性头痛微创介入治疗，超声下行各部位神经阻滞、关节软组织注射等;利用射频或等离子治疗颈腰椎间盘突出、带状疱疹性神经痛、三叉神经痛等。','周一至周日轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-017','hospital-qbj','dept-qbj-pain','QBJ-D017','蒲利华','主治中医师','硕士研究生，毕业于成都中医药大学，师从四川省中医院名老中医，从事临床诊疗工作5年，参与编写专著2部，公开发表学术论文2篇。擅长中西医结合诊治各种急慢性疼痛疾病，尤擅带状疱疹神经痛、颈肩腰腿痛、各种急慢性关节炎、骨质疏松、神经病理性疼痛等多种痛症。','周一至周日轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-018','hospital-qbj','dept-qbj-pain','QBJ-D018','胡治国','医师','硕士研究生，毕业于广西中医药大学中医骨伤科学专业，擅长运用针刺、艾灸、推拿、拔罐等方法治疗肩周炎、膝骨关节炎、腰椎间盘突出、骨质疏松以及神经病理疼痛等疾病。','周一至周日轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-019','hospital-qbj','dept-qbj-pain','QBJ-D019','宋凯麒','医师','硕士研究生，先后毕业于成都中医药大学针灸推拿学专业、重庆医科大学中医骨伤学专业，擅长运用中西医结合的方法如针刺、艾灸、推拿、拔罐等治疗肩周炎、冻结肩、膝关节炎、腰椎间盘突出、骨质疏松等疾病。','周一至周日轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-020','hospital-qbj','dept-qbj-anorectal','QBJ-D020','黄德铨','主任医师','医学博士、博士生导师。从事中医肛肠专业近四十年，擅长用中西医结合方法治疗肛肠疾病，如混合痔，肛瘘，肛周脓肿，慢性结直肠炎等。享受国务院特殊津贴专家，四川省有突出贡献优秀专家，四川省名中医，四川省卫计委领军人才，四川省卫生计生学术技术带头人。中华中医药学会肛肠分会副会长，中国民族医药学会肛肠分会副会长，中医药高等教育学会肛肠分会副会长。','周三下午','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-021','hospital-qbj','dept-qbj-anorectal','QBJ-D021','魏捷','副主任医师','毕业于成都中医药大学，从事肛肠外科工作20余年，擅长运用中西医方法结合治疗混合痔，高位复杂性肛瘘，肛周脓肿，急慢性肛裂，直肠脱垂，骶尾部藏毛窦，直肠息肉，直肠阴道瘘，肛周坏死性筋膜炎，慢性便秘等。在肛肠常见疾病的早期诊断和手术治疗领域有深入的研究。熟练操作混合痔的各种微创手术（PPH，TST，RPH）等。','周一至周日轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-022','hospital-qbj','dept-qbj-anorectal','QBJ-D022','陈海涛','主治医师','硕士研究生，毕业于成都中医药大学肛肠外科学，师从于全国著名肛肠病专家贺平教授，曾进修学习于江苏省中医院、四川省中医院等全国知名医院。从事于肛肠专科工作10年，重视肛门功能保护的手术理念及重视核磁共振引导下精准手术理念。擅长于重度环状混合痔，高位复杂性肛瘘、高位多间隙肛周脓肿，肛裂，肛乳头瘤、直肠低位息肉、肛门瘙痒症等常见肛肠科疾病；能解决肛肠科疑难复杂性疾病，如肛门狭窄、肛门失禁、直肠阴道瘘、会阴撕裂伤、骶尾部藏毛窦、骶前肿瘤、直肠脱垂、肛周坏死性筋膜炎等；掌握肛肠科复杂技术，如肛门成形术、直肠黏膜推移瓣技术、肛周皮瓣转移技术、肛门括约肌及盆底肌修补重建技术、Tropis手术、Bascom手术、Limberg手术、Delorme手术、Altemeier手术等；可运用中医药调理慢性结肠炎、肠易激综合征、顽固性肛门坠胀、顽固性肛门瘙痒等慢性肛肠病。','周一至周日轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-023','hospital-qbj','dept-qbj-anorectal','QBJ-D023','郑荣超','医师','硕士研究生，毕业于湖北中医药大学，师从国内知名专家吴汉泉教授。擅长运用中西医结合的方法治疗内痔、外痔、混合痔、肛裂、肛周脓肿、肛瘘等疾病，在肛肠微创手术、便秘、溃疡性结肠炎等领域也有深入的研究。','周一至周日轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-024','hospital-qbj','dept-qbj-anorectal','QBJ-D024','陈晓薇','医师','硕士研究生，毕业于云南中医药大学，师从云南省名中医宫毅教授。擅长运用中西医结合的方法治疗混合痔、肛裂、肛周脓肿、肛瘘、肛周湿疹、便秘、腹泻、溃疡性结肠炎等肛肠疾病。在穴位埋线、针刺八髎穴等中医特色治疗也有深入的研究。','周一至周日轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-025','hospital-qbj','dept-qbj-anorectal','QBJ-D025','张佳','医师','硕士研究生，毕业于成都中医药大学，师从陈敏教授。长期跟师四川省十大名中医曹吉勋教授、黄德铨教授。以第一作者发表论文数篇，参与国家重点研发课题一项，主持重点课题一项。擅长运用中西医结合方法诊治混合痔、肛裂、肛周脓肿、肛瘘、肛门瘙痒症、便秘、慢性结直肠炎、直肠息肉、肛乳头纤维瘤、骶尾部藏毛窦、皮脂腺囊肿、肛旁肿物等肛肠科常见病、多发病。','周一至周日轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-026','hospital-qbj','dept-qbj-derm','QBJ-D026','曾红','科室副主任、主治医师','第二届四川省医师协会优秀青年皮肤科医师 四川省整形美容协会美容皮肤分会委员 成都市整形美容协会美容皮肤分会理事 成都中西医结合学会皮肤病专委会委员 青白江区皮肤病性病质控中心组长 艾滋病治疗质控中心组长 硕士研究生，美容主诊医师，从事皮肤临床工作10年，擅长各种皮肤疾病，在皮肤美容方面有丰富的临床经验，包括色素性疾病、面部年轻化、抗衰老及瘢痕方向，如除皱、祛斑、洗纹身、祛痘坑痘印、治疗脱发等。','周一至周日轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-027','hospital-qbj','dept-qbj-derm','QBJ-D027','舒琪','主治医师','2013年毕业于川北医学院皮肤病与性病学专业，医学学士。2015年曾在成都市第二人民医院皮肤科进修学习， 2018年获得“十佳优秀医生”称号。擅长常见皮肤病、儿童皮肤病、感染性皮肤病、瘙痒性皮肤病以及皮肤肿瘤、各类性病的诊治，对激光治疗、皮肤病理活检术、果酸换肤术等治疗手段有丰富的临床经验。','周一至周日轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-028','hospital-qbj','dept-qbj-derm','QBJ-D028','孙巧梅','主治医师','医学硕士，擅长各种常见皮肤病、性病及部分少见疑难病的诊断和治疗，如皮炎、湿疹、癣、银屑病、痤疮、玫瑰痤疮、脱发、瘢痕疙瘩、面部色斑、色素痣、尖锐湿疣等。熟练操作各类光电仪器、注射及手术。毕业于遵义医科大学，曾于成都市第二人民医院规范化培训3年。四川省整形美容协会美容皮肤分会委员，成都市整形美容协会美容皮肤分会理事，参与研究市级课题多项，以第一作者发表论文3篇，获多次全国皮肤科学术年会发言及壁报交流。','周一至周日轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-029','hospital-qbj','dept-qbj-derm','QBJ-D029','方静','主治医师','医学硕士，毕业于西南医科大学皮肤病与性病学专业，主要从事皮肤病、性传播疾病的诊断及治疗。擅长常见皮肤病、过敏性皮肤病、感染性皮肤病、各种性病以及皮肤肿瘤的诊治。熟练操作CO2激光、果酸换肤、皮肤病理活检术等治疗手段。曾在北大核心期刊上发表《眼玫瑰痤疮患者60例的回顾性分析》等文章。','周一至周日轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-030','hospital-qbj','dept-qbj-aesthetic','QBJ-D030','贺强','科室主任、主治医师','中国整形美容协会分会理事 中国整形外科内镜与微创委员会成员 四川省美容整形协会眼整形分会理事 四川省卫健委整形修复科研基金负责人 医疗美容科主任，医学博士，毕业于重庆医科大学，留学法国斯特拉斯堡大学（Université de Strasbourg），Hopital Civil医院整形修复及美容外科（Chirurgie Plastique Reconstructrice et Esthétique），师从欧洲著名整形外科教授Frédéric Bodin。回国后，与意大利米兰IEO整形外科Jean-Yves Petit教授，法国巴黎居里夫人研究所（Institut Curie）Jean-guillaume FERON教授，巴西阿雷格里港医院整形外科（Hospital de Clínicas de Porto Alegre）Jorge Biazus教授等，在整形外科手术国际培训以及科研学术等方面持续进行紧密合作。专注于研究精细化整形美容手术及失败案例修复。专业特长：擅长个性化双眼皮，微创祛眼袋，耳软骨及肋软骨隆鼻，安全性隆乳术等整形美容手术以及各类美容注射项目。','周一至周五轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-031','hospital-qbj','dept-qbj-aesthetic','QBJ-D031','陈爱玲','主治医师','毕业于山东齐鲁医药学院临床医学系，学士，曾在成都市第二人民医院整形外科规培基地培训学习三年，对烧伤、整形外科有着丰富的临床诊疗经验，擅长各种颌面部精细美容缝合术、自体皮肤移植术、烧伤创面修复术、腋臭微创手术、浅表肿物切除术、激光美容以及注射美容等。','周一至周日轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-032','hospital-qbj','dept-qbj-ped','QBJ-D032','何世晔','科室主任、副主任医师','毕业于泸州医学院临床医学，从事儿科工作二十余年。先后多次参加省、市新生儿及普儿的各种学术讲座及培训班。现为青白江区医学会儿科学专业委员会副主任委员以及青白江区综合医院儿童保健质控专家组成员。擅长儿科各系统疾病，尤其是新生儿疾病的诊治。','轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-033','hospital-qbj','dept-qbj-ped','QBJ-D033','李卫','主任医师','毕业于重庆医科大学儿科系，从事儿科临床工作20余年，曾先后在四川大学华西附二院和四川省人民医院进修学习。擅长呼吸、消化系统及新生儿疾病的诊治，尤其是对慢性咳嗽、腹泻的诊治有丰富的临床经验。','轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-034','hospital-qbj','dept-qbj-ped','QBJ-D034','陈立琼','副主任医师','1993年毕业于泸州医学院，曾在重庆医科大学附属儿童医院儿科、成都市妇女儿童医院新生儿科进修学习，对儿科常见病、危急重症的诊治具有丰富的临床经验，擅长呼吸系统、消化系统及新生儿疾病的诊治。','轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-035','hospital-qbj','dept-qbj-ped','QBJ-D035','杨宗皓','副主任医师','青白江区儿科质控中心专家成员。2006年毕业于西南医科大学临床医学系，从事儿科临床一线工作十余年，曾参加成都市儿童医院住院医师规范化培训，并于成都市妇女儿童中心医院儿童重症医学科（PICU）及新生儿重症监护病房（NICU）进修学习，对儿童常见病、多发病及疑难重症的诊疗具有丰富的临床经验，尤其擅长儿童危重症及新生儿危重症的抢救和治疗。','轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-036','hospital-qbj','dept-qbj-ped','QBJ-D036','张珊','主治医师','从事儿科临床工作10余年，曾先后多次到省级、市级主办的各种培训班、讲座等进一步学习提升。擅长儿科常见疾病的诊治，特别是在呼吸系统、消化系统等疾病诊断与治疗方面积累了丰富的临床经验。从事儿科工作期间，曾多次参加儿童危急重症的抢救。对儿科罕见疾病亦有一定的见解。','轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-037','hospital-qbj','dept-qbj-ped','QBJ-D037','秦欢','主治医师','毕业于川北医学院临床医学，已从事儿科工作10余年。2019年在成都市妇女儿童医院新生儿科进一步学习新生儿疾病的治疗，先后多次到省级、市级、区级所主办的各种培训班、讲座类进一步学习提升。擅长儿科常见疾病的诊治，特别是慢性咳嗽、消化道疾病及新生儿科等疾病的诊断治疗。从事儿科工作期间，曾多次参加儿童危急重症的抢救。对儿科罕见疾病亦有一定的见解。','轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-038','hospital-qbj','dept-qbj-ped','QBJ-D038','谭小金','主治医师','毕业于赣南医学院临床医学，已从事儿科工作10余年。2019年在成都市妇女儿童医院呼吸内科进一步学习儿科呼吸科疾病的治疗，先后多次到省级、市级、区级所主办的各种培训班、讲座类进一步学习提升。擅长儿科常见疾病的诊治，特别是慢性咳嗽、消化道疾病及新生儿科等疾病的诊断治疗。从事儿科工作期间，曾多次参加儿童危急重症的抢救。对儿科罕见疾病亦有一定的见解。','轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-039','hospital-qbj','dept-qbj-ped','QBJ-D039','窦华','主治医师','2012年6月毕业于川北医学院临床医学，已从事儿科工作10余年。先后多次到省级、市级、区级所主办的各种培训班、讲座类进一步学习提升。擅长儿科常见疾病的诊治，特别是慢性咳嗽、消化道疾病及新生儿科等疾病的诊断治疗。从事儿科工作期间，曾多次参加儿童危急重症的抢救。对儿科罕见疾病亦有一定的见解。','轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-040','hospital-qbj','dept-qbj-ped','QBJ-D040','谢世成','医师','毕业于川北医学院临床医学，2016-2019年在成都市第五人民医院完成儿科住院医师规范化培训，多次参与省级、市级、区级所主办的各种培训班、讲座，擅长普儿及新生儿常见病、多发病的诊疗及儿科危急重症的处置。','轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-041','hospital-qbj','dept-qbj-ped','QBJ-D041','秦国艳','医师','毕业于川北医学院临床医学，从事儿科工作10余年。2013-2015年在四川大学临床医学系进一步学习，先后多次到省级、市级、区级所主办的各种培训班、讲座类进一步学习提升。擅长儿科常见疾病的诊治，特别是慢性咳嗽、消化道疾病及新生儿科等疾病的诊断治疗。从事儿科工作期间，曾多次参加儿童危急重症的抢救。对儿科罕见疾病亦有一定的见解。','轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-042','hospital-qbj','dept-qbj-ped','QBJ-D042','刘畅','医师','毕业于成都中医药大学临床医学，从事临床工作10余年，2011-2013年在四川大学临床医学系进一步学习，先后多次到省级、市级、区级所主办的各种培训班、讲座类进一步学习提升。擅长儿科常见疾病的诊治，尤其是在呼吸系统、消化系统以及新生儿疾病的诊治方面积累了丰富的临床经验。从事儿科工作期间，曾多次参加儿童危急重症的抢救。对儿科罕见疾病亦有一定的见解。','轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-043','hospital-qbj','dept-qbj-ped','QBJ-D043','唐诗瑾','医师','硕士研究生，2016年本科毕业于重庆医科大学临床医学，2020年硕士毕业于大理大学儿科学，2017-2020年在昆明市儿童医院完成儿科住院医师规范化培训。擅长儿科常见病、多发病的诊疗，儿科危急重症的处置。多次参与省级儿科学术年会，发表论文2篇。','轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-044','hospital-qbj','dept-qbj-child-health','QBJ-D044','梁福兵','主任医师','毕业于四川大学华西临床医学院临床医学专业，从事儿科及儿保工作20余年。先后到四川省人民医院儿童哮喘专科、四川大学华西附二院、四川大学研究生院儿科学专业、成都市妇女儿童中心等地研修学习小儿内科、新生儿科，儿童哮喘、小儿营养及生长发育、行为发育，婴幼儿早期教育干预等。擅长儿童生长发育，儿童哮喘及新生儿疾病；现主要从事儿童生长发育的临床、教学和科研工作。','周一至周五出诊；特需门诊：周二上午','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-045','hospital-qbj','dept-qbj-child-health','QBJ-D045','喻露洪','医师','2018年毕业于河北医科大学临床医学专业，并于2021年在成都大学附属医院儿科及儿保完成了3年的住院医师规范化培训，期间多次参加华西二院及成都市妇女儿童中心医院举行的学术活动及培训班。成都市青白江区儿童保健质控中心（综合医院）秘书。在儿童生长发育、营养疾病方面有一定经验，致力于儿童生长发育性疾病，儿童营养性疾病，婴幼儿佝偻病，婴幼儿贫血，锌铁缺乏等营养性疾病的防治。','周一至周五出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-046','hospital-qbj','dept-qbj-obgyn','QBJ-D046','谢帮芳','科室主任、主任医师','青白江区产科急救专家组成员 成都医学院兼职副教授 毕业于四川泸州医学院临床医学系，从事妇产科临床工作20余年，曾在四川大学华西医院及复旦大学附属妇产科医院进修学习。擅长妇科、产科、计划生育及不孕不育的常见病、多发病及疑难病症的诊治，特别是生殖内分泌及盆底功能障碍性疾病的规范化治疗，对各种难产及产科并发症、合并症的处理有丰富的临床经验，熟练掌握妇产科各类手术，尤其擅长于腹腔镜及阴式系列手术等微创技术。','产科：周三上午 妇科：周三下午','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-047','hospital-qbj','dept-qbj-obgyn','QBJ-D047','黄海龙','科室副主任、副主任医师','成都市青白江区人民医院产科急救专家组长 毕业于泸州医学院，从事妇产科专业15余年，曾在第三军医大学附属西南医院进修学习，参加英国皇家伦敦医院研修培训，主持市级科研课题一项。擅长：病理产科处理、急重症救治、妇科良恶性肿瘤及不孕症的诊治，尤其在宫、腹腔镜等微创手术方面有丰富经验。','周一出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-048','hospital-qbj','dept-qbj-obgyn','QBJ-D048','郭洪英','主任医师','医促会围产专业委员会委员、世界中联生殖医学专业委员会理事、黑龙江省医学会母胎医学专业委员会委员、成都市青白江区医学会妇科专业委员会委员。曾获黑龙江省新技术应用奖及齐齐哈尔市科技进步二等奖。从业20余年，擅长产前保健、产前筛查技术、产程观察及处理，新生儿窒息复苏，产科各种疑难危重并发症及合并症的处理。妇科各种良恶性肿瘤系统化治疗、手术，如联合多脏器切除的卵巢癌肿瘤细胞减灭术、宫颈癌广泛切除术、外阴癌根治术等，擅长腹腔镜系列手术、阴式系列手术、宫腔镜系列手术。','周四出诊；特需门诊：周二上午','#8a594d','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-049','hospital-qbj','dept-qbj-obgyn','QBJ-D049','冷红','副主任医师','四川大学研究生，妇产科门诊组组长。浙江大学关爱女性健康公益基金讲师团讲师、中国妇幼保健协会更年期专委会委员、四川省老年医学会女性健康专委会委员、四川省国际医学交流促进会生殖专委会委员、四川省预防医学会妇女保健专科能力建设专委会委员、成都市青白江区人民医院更年期保健学科带头人、成都市青白江区人民医院优秀服务明星 十佳优秀医师。从事妇产科临床工作近二十年，对妇科常见病、多发病、疑难病的诊治有丰富的临床经验。尤其擅长绝经相关疾病：更年期综合征、绝经管理、绝经激素治疗；各种原因导致的不孕不育：排卵障碍、输卵管粘连堵塞、复发性流产；月经相关疾病：多囊卵巢综合征、异常子宫出血、闭经、痛经、月经过多过少；盆底相关疾病：盆腔脏器脱垂，尿失禁，盆底评估康复；女性生殖道感染，宫颈病变；计划生育；优生咨询等。','周一至周日轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-050','hospital-qbj','dept-qbj-obgyn','QBJ-D050','冯藕','副主任医师','四川省女医师协会妇科日间手术专业委员会委员，四川省妇幼保健协会生育力保护与促进分会委员，四川省医学科技创新研究会生殖内分泌专业委员会委员，成都市妇幼健康学会女性整体康复专委会委员，青白江区医学会妇产科专委会副主任委员，青白江区产科急救专家组成员，青白江区妇产科质控专家组成员。从事妇产科临床工作20+年。曾在北京大学第三医院妇科内分泌专科进修学习，在成都市妇女儿童中心医院进修学习宫腹腔镜。多次获青白江区妇幼技能竞赛奖。获医院首届十佳优秀医师。擅长宫颈相关疾病及月经相关疾病诊治，更年期综合征，闭经，子宫内膜异位症，痛经，慢性盆腔痛，异常子宫出血，多囊卵巢综合征，宫颈病变，阴道炎，女性生殖道感染，盆底功能障碍等。对妇产科常见病，疑难病，危重急症的诊断治疗，妇科腹腔镜、宫腔镜等微创技术方面有丰富的临床经验。','轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-051','hospital-qbj','dept-qbj-obgyn','QBJ-D051','陈培蓉','副主任医师','产科助产技术、妇科疾病的诊治和产科危急重症的处理，熟练掌握各种计划生育、产科、妇科手术。','周一至周日轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-052','hospital-qbj','dept-qbj-obgyn','QBJ-D052','刘松林','副主任医师','毕业于成都医学院，妇产科工作13年，曾在四川省人民医院进修学习1年。对妇科及产科常见病，多发病诊治有丰富的经验，熟练掌握产科手术、计划生育手术及部分宫腔镜和腹腔镜手术。','轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-053','hospital-qbj','dept-qbj-obgyn','QBJ-D053','卿雪梅','主治医师','2012年毕业于成都中医药大学临床医学专业，2016年四川省人民医院妇产科专科规陪毕业回院，现西南医科大学在职研究生就读。擅长妇产科各种常见病、多发病的诊治和处理。','轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-054','hospital-qbj','dept-qbj-obgyn','QBJ-D054','屠琴','主治医师','从事妇产科临床工作十余年，在四川省人民医院等多家医院妇产专业进修学习，具有丰富的临床工作经验，基础理论扎实，能熟练进行妇产科常见病、多发疾的诊治及危急重症患者的抢救工作，妇科宫、腹腔镜微创手术操作娴熟，尤其擅长对子宫肌瘤、子宫内膜异位症等疾病的诊治；对产科妊娠合并症、并发症的诊治以及危急重症病人的抢救有很好的临床经验。','轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-055','hospital-qbj','dept-qbj-obgyn','QBJ-D055','黄利','主治医师','临床医学专业毕业，从事妇产科临床工作15年，曾在华西附二院及成都市妇女儿童中心医院进修学习生殖内分泌及产科。擅长：妇产科各种常见病、多发病的诊治，熟悉妇科生殖内分泌疾病诊治，熟练掌握计划生育手术及宫腹腔镜操作。','轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-056','hospital-qbj','dept-qbj-gi-surgery','QBJ-D056','张勇强','科室负责人、副主任医师','天津市中西医结合学会盆底疾病专业委员会 委员 天津市抗衰动物致伤处置专业委员会 委员 天津市中西医结合学会循证医学会 青年委员 2008年毕业于西南医科大学临床医学系，曾先后于天津市肿瘤医院、四川大学华西医院等国内知名医院进修深造，具备系统的专业理论知识与前沿的临床诊疗视野。获评市级“优秀医师”、区级“十佳好医生”等多项荣誉称号，拥有十七年三级综合医院临床工作经验，在肝胆胰疾病的临床诊治方面积淀深厚。擅长腹腔镜胆囊切除术、双镜联合胆总管探查取石一期缝合术、腹腔镜下肝段切除术、肝部分切除术等肝胆胰外科手术。对急性重症胰腺炎的治疗有独到见解。','周二上午','#315b79','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-057','hospital-qbj','dept-qbj-gi-surgery','QBJ-D057','刘成建','胃肠疝专业组组长、主治医师','毕业于泸州医学院，从事外科临床工作20余年。对普通外科疾病诊治积累了丰富的临床经验，尤其擅长胃肠道肿瘤、甲状腺及乳腺疾病的诊治。','周一上午；周日上午；轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-058','hospital-qbj','dept-qbj-gi-surgery','QBJ-D058','李长华','副主任医师','毕业于重庆医科大学，从事外科临床工作20余年。擅长胃肠道肿瘤、甲状腺、乳腺、下肢静脉曲张疾病的诊断和治疗。','周三、周五上午；周日上午；轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-059','hospital-qbj','dept-qbj-gi-surgery','QBJ-D059','胡志坤','肝胆胰专业组组长、副主任医师','重庆医科大学临床医学系毕业，从事肝胆胰外科20余年。在肝癌，胆管癌，胰腺良恶性肿瘤，胆道结石的诊治方面有丰富的临床经验，擅长精准肝切除，胆管癌根治术，胰腺癌扩大根治术，腹腔镜肝外胆管结石手术治疗，腔镜甲状腺良性肿瘤切除术。','周五上午；周六上午；轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-060','hospital-qbj','dept-qbj-gi-surgery','QBJ-D060','陈杨东','副主任医师','毕业于河北医科大学临床医学专业，于重庆第三军医大学西南医院肝胆外科进修。从事肝胆胰系统疾病的临床诊治工作20余年，具有扎实的肝胆胰腺专业理论知识。掌握本专业国内外最新发展动态，对肝胆胰系统常见病、多发病及疑难危重疾病有丰富的临床诊治经验，尤其擅长复杂肝胆管结石诊断及微创手术治疗。','周三上午；周六上午；轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-061','hospital-qbj','dept-qbj-gi-surgery','QBJ-D061','龙飞','副主任医师','毕业于重庆医科大学临床医学专业，从事肝胆胰外科外科工作18年，在四川省人民医院肝胆外科进修学习。擅长复杂肝胆管结石的外科手术治疗、肝脏、胰腺肿瘤的外科手术治疗、术中、术后肝胆管结石胆道镜碎石、取石，及肝胆外科各种危急重症治疗。','周一上午；周六上午；轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-062','hospital-qbj','dept-qbj-breast-thoracic','QBJ-D062','佘军','科室主任、主任医师','从业27年，先后在哈医大肿瘤医院乳腺科、上海复旦肿瘤医院乳腺科、天津肿瘤医院乳腺科、山东省肿瘤医院乳腺科进修学习。对乳腺各类疾病诊治具有丰富的临床经验，擅长乳腺癌系统、个体化、精准治疗及乳腺良性疾病保守治疗，率先在青白江及周边开展乳腺肿物旋切术、乳腺癌保乳手术、乳腺癌根治及重建术。','周一、；周三全天','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-063','hospital-qbj','dept-qbj-breast-thoracic','QBJ-D063','蒋修全','主任医师','毕业于川北医学院临床医学。对胸部各类疾病的诊治具有丰富的临床经验，擅长胸部疾病如胸痛、肋骨及胸骨骨折、血气胸、食管肿瘤、肺癌、肺结节、纵隔肿瘤的诊治，并率先在青白江及其周边区域开展了食管癌、肺癌、纵隔肿瘤、肋骨骨折等的微创手术，鸡胸及漏斗胸的胸廓成形手术。','周一、；周三上午','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-064','hospital-qbj','dept-qbj-breast-thoracic','QBJ-D064','贾玲','主治医师','毕业于西南医科大学，从事临床工作10余年，曾多次参加省、市级乳腺培训班，擅长治疗乳腺炎、乳腺增生、乳腺纤维腺瘤、乳腺癌及乳腺癌术后化疗等疾病。','周四全天','#765a79','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-065','hospital-qbj','dept-qbj-breast-thoracic','QBJ-D065','张凯','主治医师','2015年毕业于齐齐哈尔医学院临床医学专业，曾在齐齐哈尔医学院附属第三医院进行全国住院医师规范化培训3年。 主要擅长：甲状腺、乳腺良恶性肿瘤疾病诊断与治疗；哺乳期乳腺炎、乳腺脓肿、非哺乳期乳腺炎治疗；乳腺结节微创手术；乳腺肿瘤穿刺取病检；乳腺恶性肿瘤术后化疗、内分泌治疗等。','周二全天','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-066','hospital-qbj','dept-qbj-breast-thoracic','QBJ-D066','吴丽娜','医师','毕业于重庆医科大学，硕士研究生，擅长乳腺、甲状腺常见疾病的诊疗，掌握乳腺微创手术，乳头溢液灌洗治疗，乳腺结节切除术，乳腺结节穿刺术。','周五全天','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-067','hospital-qbj','dept-qbj-breast-thoracic','QBJ-D067','王海军','主治医师','2011年毕业于川北医学院临床医学系，2017年获得西南医科大学硕士研究生学位，擅长骨科及胸外科常见疾病的诊治。','周二上午','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-068','hospital-qbj','dept-qbj-breast-thoracic','QBJ-D068','袁管明','医师','毕业于成都大学临床医学院；擅长对肺部结节、肺大疱、自发性气胸、纵隔肿瘤、胸壁肿瘤、胸部外伤、食管肿瘤等胸外科常见疾病的诊断及治疗。','周五上午','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-069','hospital-qbj','dept-qbj-breast-thoracic','QBJ-D069','丁袁','主治医师','擅长肺结节，食管疾病，肺癌，纵膈肿瘤，自发性气胸，胸部外伤等胸外科疾病的诊治和手术治疗。','周四上午','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-070','hospital-qbj','dept-qbj-card','QBJ-D070','兰蓉','学科主任、主任医师','成都市急诊质量控制专家，1993年毕业于重庆医科大学。擅长心血管内科难治性高血压、冠心病、各种心律失常等常见病的诊治。对内科危重症抢救治疗有丰富的临床经验。','轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-071','hospital-qbj','dept-qbj-card','QBJ-D071','杜海林','科室主任、副主任医师','硕士研究生，日本国立岛根大学访问学者，四川省医师协会心血管临床试验研究者分会委员，四川省康复医学会心血管重症专委会委员，成都市医学会心血管专委会委员，参研国家自然科学基金项目1项、省卫健委科研项目1项、省医学会科研项目1项、市卫健委科研项目1项，主持省医学会科研项目1项、市卫健委科研项目1项，发表SCI论文1篇，核心期刊论文10篇。擅长心血管疾病介入治疗，如冠心病介入、起搏器植入及结构性心脏病介入，特别是复杂冠脉介入，年完成心血管介入诊疗手术近1000台次。','周二上午、周末轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-072','hospital-qbj','dept-qbj-card','QBJ-D072','薛斌','科室副主任、副主任医师','毕业于泸州医学院临床医学系，从事心血管内科专业20余年，曾先后在四川大学华西医院进修心血管内科诊疗技术，在第三军医大学西南医院进修心脏介入技术。擅长急慢性心力衰竭、心律失常、冠心病、高血压病、肺心病、风心病等心脏急危重症诊疗以及冠状动脉造影及支架植入术、心律失常射频消融术、心脏起搏器植入术的介入治疗。','轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-073','hospital-qbj','dept-qbj-card','QBJ-D073','陈涛','科室副主任、副主任医师','从事心内科内科工作13年。现任四川省国际医学交流促进会心律失常专委会委员、青白江医学会心内科副主任委员。先后于国家心血管病研究所北京阜外心血管病医院及四川省人民医院心血管内科进修学习。擅长心血管常见病及疑难重症的诊治、各种复杂心律失常的射频消融治疗、冠心病介入治疗、各种心脏起搏器植入治疗。发表学术论文数篇。','轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-074','hospital-qbj','dept-qbj-card','QBJ-D074','吴晓宇','副主任医师','医学学士，毕业于泸州医学院临床医学专业，长期从事临床工作，曾在四川大学华西医院心血管内科进修学习，擅长诊治心内科疑难危重病例，尤其对冠心病、糖尿病、高血压、顽固性心力衰竭、心律失常、脑梗塞、脑出血、脑动脉硬化等疾病的治疗有较深的研究。','轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-075','hospital-qbj','dept-qbj-card','QBJ-D075','谭周杰','主治医师','毕业于武汉科技大学，从事心内科临床工作10余年。曾于四川大学华西医院进修冠脉介入手术培训。擅长冠心病，高血压，心力衰竭，心律失常，心肌病，心肌炎等等心血管内科常见病、多发病的诊治。','轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-076','hospital-qbj','dept-qbj-card','QBJ-D076','杜宏磊','主治医师','毕业于川北医学院，本科学历，于宜宾市第一人民医院完成住院医师规范化培训。擅长冠状动脉粥样硬化性心脏病、风湿性心脏病、心脏瓣膜病、心律失常、心力衰竭、急性心肌梗死、高血压、心肌病等心内科疾病诊疗及危急重症抢救。','轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-077','hospital-qbj','dept-qbj-card','QBJ-D077','纪洪凯','主治医师','2011年毕业于成都医学院临床医学专业，大学本科，学士学位。2013年取得执业医师资格证、2015年取得规范化培训资格证；2018年于四川大学华西医院进修心脏病内科并顺利结业；2021年取得主治医师资格。长期从事心血管内科临床工作，擅长冠心病、高血压急症、心力衰竭、心肌病及心律失常等心血管内科疾病诊治。','轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-078','hospital-qbj','dept-qbj-card','QBJ-D078','况元明','主治医师','毕业于泸州医学院临床医学专业，本科，学士学位，毕业后长期从事临床内科工作，于2016年在四川大学华西医院进修学习一年并顺利结业，2018年通过副主任医师资格考试，在各类期刊杂志发表学术论文数篇，擅长于高血压急症、顽固性心力衰竭、冠心病、心律失常、心肌病等心内科疾病的诊治。','轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-079','hospital-qbj','dept-qbj-card','QBJ-D079','李春丽','主治医师','毕业于泸州医学院临床医学系，学士学位，中共党员，先后在成都第五人民医院及延安大学咸阳医院进修学习。从医10余年，擅长高血压、冠心病、扩心病、心力衰竭等心内科常见病、多发病的诊治。','轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-080','hospital-qbj','dept-qbj-card','QBJ-D080','谯英','主治医师','毕业于四川大学华西临床医学院。于四川省人民医院进行住院医师3年规范化培训。长期从事心血管内科临床工作。擅长:高血压、冠心病、心律失常、顽固性心力衰竭、心肌梗死等心血管内科疾病的诊治。','轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-081','hospital-qbj','dept-qbj-card','QBJ-D081','龙伟','主治医师','2013年毕业于成都医学院，本科学历，于四川省人民医院规范化培训三年，从事心内科工作4年，能对心内科常见病如高血压、冠心病、心律失常、心肌病、急慢性心力衰竭、急性心肌梗死等进行诊治。','轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-082','hospital-qbj','dept-qbj-resp','QBJ-D082','周黎强','科室主任、主任医师','先后荣获“成都市科技进步三等奖”、“成都市科技进步二等奖”。2015年荣获首届“四川好医生”称号。成都市医疗事故专家鉴定委员会成员、成都市防痨协会第七届理事会理事、四川省预防医学会呼吸系统疾病防治分会第1和2届委员会常务委员、四川省医学会呼吸学分会烟草病学组副组长、中国戒烟联盟理事、成都市青白江区人民医院呼吸与危重症医学科主任。从事内科工作30年，其中呼吸专业25年。擅长于急性咳嗽、慢性咳嗽、咯血、胸痛、慢阻肺、哮喘、间质性性肺疾病、肺部结节、肺部包块、烟草依赖综合征的诊断和治疗。尤其是呼吸专业疑难、危重症患者的诊疗、呼吸道内镜介入、有创和无创呼吸机使用等方面积累了丰富临床经验。长期致力于哮喘和慢阻肺规范化与个体化精准治疗以及科学的戒烟方法和技巧的推广，烟草成瘾戒断率国内领先，达到60%左右。','特需门诊：周三上午','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-083','hospital-qbj','dept-qbj-resp','QBJ-D083','梁英','副主任医师','全科医师师资，毕业于泸州医学院，从事内科临床工作20余年。曾在四川省人民医院内科、纤支镜室，四川大学华西医院呼吸科进修学习。擅长肺炎、急性支气管炎、慢性支气管炎、慢阻肺、肺心病、支气管哮喘、支气管扩张、气胸、慢性咳嗽等呼吸科常见病、多发病的诊治。','周一至周五全天 周末轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-084','hospital-qbj','dept-qbj-resp','QBJ-D084','胡溢','副主任医师','毕业于泸州医学院，目前为西南医科大学在职研究生。曾于华西医院呼吸危重症、纤支镜、肺功能室、经皮肺穿刺等相关专业科室进修学习。擅长呼吸内科常见病、多发病及疑难疾病的规范化诊疗；尤其擅长对肺结节、胸腔积液等复杂疑难疾病的处置及纤维支气管镜、内科胸腔镜等呼吸介入的处置。','周一；上午、；周末轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-085','hospital-qbj','dept-qbj-resp','QBJ-D085','陈李','副主任医师','擅长:肺部感染性疾病、慢阻肺、哮喘、呼吸危重症、胸积液的诊治。尤其擅长:纤支镜、胸腔镜、经皮肺穿刺检查，擅长呼吸机及支气管镜介入治疗。','轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-086','hospital-qbj','dept-qbj-infectious','QBJ-D086','邓君','副主任医师','毕业于重庆医科大学，从事内科临床工作20余年。擅长肺部感染性疾病、慢支炎、肺心病、支气管哮喘、慢性咳嗽、肺结核、气胸、胸腔积液、慢性咳嗽等呼吸科常见病、多发病的诊治。','周一至周五轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-087','hospital-qbj','dept-qbj-endo-neph','QBJ-D087','刘娟','科室主任、主任医师','四川省老年内分泌暨糖尿病专委会委员、四川省国际医学交流促进会骨质疏松骨病专业委员会常委、成都市内分泌质控中心专家、成都高新医学会内分泌专委会常委、成都市青白江区医学会内分泌专委会主任委员。从事内科工作29年，内分泌工作10余年。毕业于川北医学院临床医学专业，曾先后到西南医院、四川大学华西医院内分泌科及成都市第二人民医院肾脏内科进修学习。擅长内分泌、肾内疾病的诊治,如糖尿病、甲状腺等疾病。','周三上午 特需门诊：周一上午','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-088','hospital-qbj','dept-qbj-endo-neph','QBJ-D088','胡文兴','科室副主任、副主任医师','重庆医科大学研究生毕业，医学硕士，从事内科临床工作20余年,曾在四川大学华西医院、第三军医大学西南医院、成都市第二人民医院肾内科及血液净化中心进修学习。擅长肾脏疾病、风湿免疫性疾病及内分泌疾病的诊治，能熟练进行血液净化技术、血管通路手术及肾穿刺活检术。','周一、周四上午、周末轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-089','hospital-qbj','dept-qbj-endo-neph','QBJ-D089','刘志','副主任医师','毕业于泸州医学院，曾在华西医院进修学习,参与多项省、市级科研及继续教育项目。擅长糖尿病、甲状腺疾病、骨代谢疾病、肾上腺疾病、垂体疾病等疾病的诊治，尤其在糖尿病、骨质疏松症方面有丰富的临床经验。','周二、周五上午、周末轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-090','hospital-qbj','dept-qbj-endo-neph','QBJ-D090','常健娟','主治医师','四川省预防医学会内分泌代谢性疾病防控分会青年委员，成都市内分泌质控中心青白江区分中心秘书，青白江区医学会内分泌专业委员会副主任委员。2006年毕业于西南医科大学，从事内科临床工作17年，2017年-2018年于四川大学华西医院内分泌与代谢科专科进修一年，擅长内分泌代谢疾病如糖尿病、甲状腺疾病、继发性高血压、高尿酸血症、肾上腺疾病及垂体疾病的诊治。','轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-091','hospital-qbj','dept-qbj-endo-neph','QBJ-D091','程驰航','主治医师','河北医科大学本科毕业，从事内分泌临床工作 10 年，擅长糖尿病、痛风、甲状腺疾病、骨质疏松等内分泌专科疾病。','轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-092','hospital-qbj','dept-qbj-endo-neph','QBJ-D092','李衍辉','主治医师','医学硕士，毕业于西南医科大学内分泌学专业，曾于成都市第二人民医院规范化培训2年。以第一作者发表SCI一篇，在北大核心期刊发表论文3篇，曾多次获中华医学会内分泌学术年会壁报交流。擅长内分泌及代谢性疾病常见病的诊治。','轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-093','hospital-qbj','dept-qbj-endo-neph','QBJ-D093','张佳敬','主治医师','毕业于成都医学院临床系，医学学士。从医10余年，曾到华西医院进修学习1年。擅长糖尿病、甲亢、甲减、肾上腺疾病的诊治，尤其对糖尿病足病、溃疡、褥疮等疾病有较深的研究。','轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-094','hospital-qbj','dept-qbj-resp-chronic','QBJ-D094','刘泽辉','主任医师','毕业于华北理工大学，曾在北京朝阳医院、重医附一院、西南医院、四川省人民医院、成都军区总院进修。从事内科临床工作30余年，在省部级杂志上发表论文20余篇。长期从事呼吸和消化内科常见病及疑难杂症的诊断及治疗工作，诊疗范围包括熟练掌握支气管镜、胸腔镜、胃镜、肠镜、十二指肠镜的操作及镜下治疗。肺气肿减容术、肺大泡摘除术、难治性恶性胸腔积液胸膜固定术、难治性气胸胸膜修补术、难治性气胸支气管胸膜瘘封堵术，镜下取活检、气道异物取出、支气管肺泡灌洗、大容量全肺灌洗、纵隔淋巴结活检、透壁肺活检、气管、支气管狭窄球囊扩张。难治性肺部感染性疾病经鼻—肺置管技术，纵隔置管引流治疗纵隔脓肿术。食道支架植入、气管支架植入及ERCP操作及胸腔镜镜下诊断及治疗。其中，大容量全肺灌洗术、经鼻—肺置管治疗难治性肺部感染、纵隔置管引流治疗纵隔脓肿术，在西南地区具有开创性技术。','周一至周三区人民医院门诊，周四姚渡镇卫生院坐诊，周五轮流在大弯社区卫生服务中心、大同镇卫生院、城厢镇公立中心卫生院、祥福镇公立中心卫生院、龙王镇卫生院坐诊。','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-095','hospital-qbj','dept-qbj-health-mgmt','QBJ-D095','王向军','主任医师','四川省康复医学会呼吸专委会青年委员、成都市医师协会呼吸专委会青年委员、西部呼吸介入联盟理事。2004年毕业于重庆医科大学临床医学系，2012-2014年于泸州医学院在职研究生班学习。曾在四川大学华西医院进修呼吸内科专业、RICU和纤支镜操作，2014年获得“四川省二类呼吸内镜诊疗技术临床应用能力规范化培训班”结业证书；2019年获得“华西-chest呼吸与危重症学院气管镜规范化培训班”结业证书。擅长胸膜活检、经皮肺穿刺、深静脉穿刺和电子支气管镜、胸腔镜、呼吸机的操作。','轮换出诊，具体以当日排班为准','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-096','hospital-qbj','dept-qbj-weight-mgmt','QBJ-D096','高波','临床营养科主任、副主任医师','临床营养科主任 四川省老年学学会老年营养专业委员会委员 四川省医院协会医务管理分会理事 成都市医学会理事 1992年毕业于川北医学院临床医学专业。在四川大学华西医院消化内科进修学习胃镜肠镜检查。擅长消化患者、危重患者、手术患者及肿瘤患者的营养诊疗和营养干预，对亚健康人群的健康教育、体重管理具有丰富经验。','周四下午','#8a594d','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-097','hospital-qbj','dept-qbj-psych','QBJ-D097','钟爱','医师','毕业于哈尔滨医科大学，主修精神医学。规培医院：昆明市第一人民医院、云南省精神病医院。擅长青少年心理疾病、睡眠障碍、焦虑抑郁等疾病诊治。','周一、周三、周五全天，周二、周四上午','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-098','hospital-qbj','dept-qbj-gastro','QBJ-D098','周维珍','学科主任、主任医师','华西医科大学临床医学专业毕业。成都市医学会感染专科分会委员、成都市高新医学会消化专科委员、成都市消化质量控制中心专家、成都市艾滋病质控中心专家。曾在西南医院消化内科、四川省人民医院窥镜室、成都市第二人民医院消化内科进修学习。2019年科研项目《建立基于临床、内镜危险程度的消化性溃疡出血的治疗策略》获市级医学科技奖三等奖，荣获成都市青白江区人民医院第一届“青梁人才”，发表论文数篇。擅长消化系统疾病的诊治，如食道炎、消化性溃疡、消化道出血、胰腺炎、胃肠道肿瘤、炎症性肠病等的诊断及治疗；各种肝病的诊治:如乙肝、丙肝的抗病毒治疗及肝炎后肝硬化失代偿期的治疗。','周二全天、周四上午 特需门诊：周一上午','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-099','hospital-qbj','dept-qbj-gastro','QBJ-D099','梁川','科室主任、副主任医师','泸州医学院临床医学专业毕业，从事内科临床工作20余年，先后在成都军区总医院、四川大学华西医院、复旦大学中山医院进修学习。擅长消化系统疾病诊疗，消化内镜操作及内镜下治疗。','周一、周三上午','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-100','hospital-qbj','dept-qbj-gastro','QBJ-D100','张小龙','副主任医师','四川省医学传播学会消化营养健康专委会委员 四川天府新区医学科技创新促进会委员 先后于四川大学华西医院、首都医科大学附属北京友谊医院进修消化内科及消化内镜。对消化专业相关的常见病、多发病能熟练进行诊治，并具备较强解决复杂、疑难、危重消化专科问题的能力；能熟练进行胃肠镜检查、胶囊内镜检查及内镜下诊疗：内镜下止血、异物取出、支架植入、EMR、ESD、放大内镜、超声内镜等。','轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-101','hospital-qbj','dept-qbj-gastro','QBJ-D101','梁平','副主任医师','医学学士，2007年毕业于泸州医学院临床医学专业，从事消化内科临床诊治工作16年。现任四川省中西医结合学会消化内镜专业委员会委员，四川省生物信息学学会消化微创分会委员，四川天府新区医学科技创新促进会委员，四川省医学传播学会消化营养健康专业委员会委员。曾先后于四川大学华西医院、四川省肿瘤医院进修学习消化内科及消化内镜诊治技术。目前主要从事消化内科常见病、多发病的诊断与治疗。在消化内镜诊治方面具有一定专长，主持开展消化内科新技术两项，主持开展四川省医学会科研课题一项，主持成都市卫健委科研课题一项，参研市级科研课题多项。目前主要亚专业方向为消化道早癌诊断与治疗。','轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-102','hospital-qbj','dept-qbj-gastro','QBJ-D102','谢智','主治医师','2007年毕业于泸州医学院临床医学专业，从事消化内科专业13年，曾在成都市第一人民医院内科规培一年，在四川大学华西医院进修消化内科和消化内镜专业一年。擅长：消化内科常见病多发病诊治、消化内科危重症的处理、胃肠镜检查、胶囊内镜检查及部分内镜下治疗。','轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-103','hospital-qbj','dept-qbj-gastro','QBJ-D103','杨浪','主治医师','毕业于成都中医药大学临床医学系，从事消化内科工作多年，曾在四川大学华西医院消化内科及内镜中心进修学习。擅长消化内科各种常见病及疑难病的诊治，尤其擅长胰腺炎、消化性溃疡、慢性乙型病毒性肝炎、肝硬化、慢性胃炎等疾病的诊治，胃、肠镜操作及内镜下治疗。','轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-104','hospital-qbj','dept-qbj-gastro','QBJ-D104','赖瑞雪','主治医师','毕业于河北医科大学，研究生学历，曾在河北医科大学第四医院工作3年余。擅长消化性溃疡、慢性胃炎、食管炎、肠炎、各种感言、肝硬化、消化道出血等消化系统常见病的诊治，发表多篇SCI。','轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-105','hospital-qbj','dept-qbj-neuro','QBJ-D105','邱霞','学科主任、副主任医生','四川省康复医学会神经专委会委员、四川省医学会头痛病学组委员、四川省全科医学带教师资、成都市神经内科质控专家。从事临床近30年，曾在四川大学华西医院神经内科、四川省人民医院神经内科、成都医学院附属医院神经内科进修学习。临床功底扎实，擅长脑血管疾病、偏头痛、神经变性等神经内科常见病和疑难病诊治。发表文章约10篇，编写著作1部。','周三全天、周四上午、周末轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-106','hospital-qbj','dept-qbj-neuro','QBJ-D106','王运锋','科室主任、副主任医生','四川省医创会神经内科创新及转化分会委员、四川省生信学会神经病学分会委员、四川省医学会高压氧专委会青年委员、南充市医学会神经介入学组组员。医学博士，曾主持省市级科研课题3项。以第一作者及共同第一作者发表SCI论文3篇，第一作者发表中文核心论文7篇。擅长：治疗急性缺血性脑卒中的机械取栓治疗、脑动脉狭窄的介入治疗；偏头痛、药物过度使用性头痛、慢性头痛、复发性眩晕、帕金森病、老年性痴呆、吉兰巴雷综合征的规范化诊断和治疗。','周二、周五上午、周末轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-107','hospital-qbj','dept-qbj-neuro','QBJ-D107','万鹏程','副主任医生','四川省卒中委员会介入组委员、四川省中医药学会神经介入委员会委员、成都市神经科病历管理专家库成员、成都医师协会神经内科专委会委员。神经专科硕士 ，毕业于泸州医学院，从事医学专业20余年，曾在四川省人民医院.四川省医学科学院工作研修4年。擅长神经内科疾病处理、急重症病人抢救、脑血管的诊治，尤其是对急性缺血性脑卒中的治疗有丰富经验。长期从事临床带教工作，教学经验丰富，第一作者发表核心期刊学术论文多篇。','周一、周三上午、周末轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-108','hospital-qbj','dept-qbj-neuro','QBJ-D108','胡艳梅','主治医师','神经病学硕士，研究生毕业于桂林医学院。曾于成都医学院第一附属医院规范化学习2年，具有丰富的神经内科临床经验。擅长脑梗死、头晕、面瘫、神经痛、睡眠障碍等神经科常见疾病的诊治，对帕金森病、老年痴呆发病及病理有一定研究，发表专业论文6篇。','轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-109','hospital-qbj','dept-qbj-neuro','QBJ-D109','邓萍萍','主治医师','硕士学位，毕业于西南医科大学神经病学专业，从事神经内科医疗工作6年余，擅长癫痫，急性脑梗死的规范化治疗，头晕、头痛、颅内感染、变性疾病的诊断及治疗。','轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-110','hospital-qbj','dept-qbj-neuro','QBJ-D110','童娅','主治医师','学士学位，毕业于成都医学院临床医学系。从事神经内科医疗工作9年余，2020年3月于四川大学华西医院神经内科进修结业。擅长急性脑梗死的规范化治疗，头痛、头晕、癫痫、颅内感染、变性疾病的诊断及治疗。','轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-111','hospital-qbj','dept-qbj-neuro','QBJ-D111','段玲','主治医师','本科学历，学士学位，从事神经内科临床工作7年余，曾在西南医科大学第一附属医院神经内科进行3年住院医师规范化培训。擅长：头痛头晕、手脚麻木、脑中风、脑出血、三叉神经痛、癫痫、帕金森病、周围神经病、老年性疾病等神经内科疾病的诊治。','轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-112','hospital-qbj','dept-qbj-intervention','QBJ-D112','曹磊','科室主任、副主任医师','主持省、市科研课题多项，发表多篇论著报道；于首都医科大学附属天坛医院、四川大学华西医院、成都市第二人民医院进修、学习：肿瘤、血管、神经方面疾病；从事肿瘤、血管、介入综合治疗多年，率先在全省区县级人民医院开展食管癌、胆管癌、结肠癌等支架置入术；肺癌、肝癌、胃癌、结直肠癌、胰腺癌动脉化疗栓塞术，腔静脉滤器置入/回收术，深静脉血栓溶栓、动静脉闭塞开通支架置入术、主动脉夹层、主动脉瘤支架植入术、神经介入治疗，输液港（动脉港/静脉港）植入以及动脉灌注术等20余项微创介入手术，填补了青白江区相关疾病治疗空白，临床经验丰富，对肿瘤、血管疾病的综合治疗有独特见解。同时，科室被授予“全国难治性癌痛示范基地”和“中国无痛介入联盟”，在全国具有一定知名度及影响力。','周一上午','#765a79','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-113','hospital-qbj','dept-qbj-intervention','QBJ-D113','刘彬','主治医师','成都市抗癌协会肿瘤介入专委会委员 于成都市第二人民医院进修、学习：肿瘤、血管方面疾病；从事肿瘤、血管、介入综合治疗多年，擅长综合微创介入治疗及肿瘤综合治疗，开展食管癌、胆管癌、结肠癌等支架置入术；肺癌、肝癌、胃癌、结直肠癌、胰腺癌动脉化疗栓塞术，腔静脉滤器置入/回收术，深静脉血栓溶栓，输液港（动脉港/静脉港）植入以及动脉灌注术等10余项微创介入手术。','周一至周五上午','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-114','hospital-qbj','dept-qbj-intervention','QBJ-D114','郭秉乾','医师','医学学士，毕业于川北医学院，先后至多家三甲医院工作学习，于成都市第五人民医院顺利规培结业，从事普外科方向多年。擅长血管外科常见疾病的诊断及治疗，包括动脉血管的狭窄、闭塞、血栓闭塞性脉管炎、动脉栓塞、雷诺综合征、动脉炎、动脉损伤、动静脉瘘、静脉炎、静脉瓣膜功能不全、原发性下肢静脉曲张、静脉血栓形成、静脉损伤、淋巴回流受阻的疾病等。','轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-115','hospital-qbj','dept-qbj-intervention','QBJ-D115','刘正','医师','医学硕士，新疆医科大学外科学专业，完成住院医师规范化培训于新疆医科大学第二附属医院。系统掌握普外科及血管外科诊疗技术，具备扎实的临床操作与理论基础。专注于血管外科疾病的规范化诊疗。擅长动静脉疾病如：动脉硬化狭窄/闭塞、血栓闭塞性脉管炎、动脉栓塞、下肢静脉曲张、深静脉血栓形成、静脉瓣膜功能不全、静脉炎等疾病。旨在以患者需求为核心，制定个体化阶梯治疗方案 ；建立慢性血管疾病长期随访机制，动态调整治疗策略 ；通过通俗易懂的科普宣教，提升患者自我健康管理能力。','轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-116','hospital-qbj','dept-qbj-intervention','QBJ-D116','郭亮','医师','医学学士，毕业于川北医学院，于成都市第五人民医院放射肿瘤专业医师规范化培训；擅长：癌痛规范化治疗，肺癌、食管癌、肝癌、胃癌、结直肠癌、宫颈癌等实体肿瘤的综合治疗。','轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-117','hospital-qbj','dept-qbj-radiotherapy','QBJ-D117','方红','科室主任、主任医师','毕业于川北医学院医学系临床医学专业，从事肿瘤临床工作20余年，曾先后在中山大学附属肿瘤医院、四川大学华西第四医院、四川省肿瘤医院进修，学习。擅长肺癌、乳腺癌、鼻咽癌、结直肠癌、食管癌、卵巢癌、宫颈癌、肝癌等常见恶性肿瘤的诊断与治疗，恶性肿瘤姑息治疗及癌症筛查与早诊。在国家级核心期刊发表学术论文十余篇、SCI论文1篇。在省市十余个专委会有学术任职。','周一、周四上午','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-118','hospital-qbj','dept-qbj-radiotherapy','QBJ-D118','王蕾','主治医师','成都市抗癌协会康复专委会委员、成都市抗癌协会高新医学会肿瘤专委会青委、四川省肿瘤学会头颈部肿瘤专委会委员、肿瘤放疗科医疗组长，经过放射肿瘤专科规范化培训。擅长：各类肿瘤疾病的筛查、诊断及治疗，癌痛PCA镇痛技术，肿瘤深部热疗，肿瘤放射治疗。','周五上午','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-119','hospital-qbj','dept-qbj-radiotherapy','QBJ-D119','邓鹏程','主治医师','肿瘤学硕士，中国抗癌协会鼻咽癌专业委员会会员、中国抗癌协会肿瘤多学科诊疗专业委员会会员、中国抗癌协会医学物理技术专业委员会会员、四川省抗癌协会会员、四川省生物信息学会会员。擅长实体肿瘤的放疗、化疗、靶向治疗、免疫治疗及多学科综合治疗，能为患者提供精准的个体化治疗方案。','周三上午','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-120','hospital-qbj','dept-qbj-radiotherapy','QBJ-D120','李仁桐菲','主治医师','2012年毕业于西安医学院，曾于成都市第二人民医院完成临床医师规范化培训，擅长肿瘤内科相关诊查、肿瘤化疗、热疗、靶向治疗、癌痛规范化治疗、肿瘤营养支持治疗等。','轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-121','hospital-qbj','dept-qbj-rehab','QBJ-D121','吴蔚然','科室主任、主任医师','成都市康复医学会理事，成都市神经康复专委会常委，成都市高压氧质控中心专家，成都市长期照护险评估委员会专家。毕业于川北医学院临床医学专业，从事临床工作20余年，曾于重庆市第三军医大学新桥医院进修内分泌专业，成都市第二人民医院进修康复医学，擅长代谢性疾病康复，神经康复，社区康复，老年康复，发表多篇学术论文，主持成都市卫健委科研课题1项，参研国家重点研发课题2项，获国家新型实用专利2项。','轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-122','hospital-qbj','dept-qbj-rehab','QBJ-D122','韩榛','主治医师','毕业于泸州医学院临床医学系，曾于成都市第二人民医院进修康复医学和冲击波治疗技术，现任成都市康复医学会骨关节炎康复专委会委员，成都市长期照护险评估人员。擅长肌骨康复、冲击波治疗技术、关节腔灌注技术。参与成都市科技局惠民科研项目1项，获国家新型实用专利1项。','轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-123','hospital-qbj','dept-qbj-rehab','QBJ-D123','尹东琼','主治医师','毕业于成都中医药大学临床医学院，曾于成都市第二人民医院进修康复医学，现任四川省康复医学会阿尔兹海默症及认知障碍专委会委员，擅长老年康复和认知功能障碍康复治疗，运用中医内治在中风偏瘫、焦虑失眠、脾虚纳差方面疗效显著。','轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-124','hospital-qbj','dept-qbj-rehab','QBJ-D124','戴秀娟','主治医师','毕业于川北医学院，擅长颈椎病，腰椎病，骨质疏松，老年骨关节病，脑卒中后偏瘫，颅脑损伤，脊髓损伤等疾病的康复治疗，以及睡眠障碍，抑郁、焦虑状态的经颅磁刺激的治疗。','轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-125','hospital-qbj','dept-qbj-rehab','QBJ-D125','邱潍','主治医师','毕业于成都医学院，长期从事临床工作，曾于成都市第二人民医院完成康复医学科住院医师规范化培训。擅长神经康复、颈腰椎病康复及代谢性疾病康复治疗。','轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-126','hospital-qbj','dept-qbj-rehab','QBJ-D126','魏冬梅','医师','毕业于泸州医学院，2019年于成都市第一人民医院进修高压氧，擅长颈椎病、腰椎病、卒中后偏瘫、面瘫等疾病治疗。','轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-127','hospital-qbj','dept-qbj-ent-ophth','QBJ-D127','张德强','科室主任、主治医师','师从钟守国教授及樊映川教授，曾在四川省人民医院眼科进修。熟练掌握各种眼科手术如:前房穿刺术，虹膜周切术，青光眼小梁切除术，白内障摘除术+人工晶体植入术，抗青光眼手术，眼睑裂伤缝合术，角膜和巩膜裂伤清创缝合术等外眼内眼手术。擅长眼科及耳鼻咽喉科常见病，多发病的诊治。','周一全天、周四上午','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-128','hospital-qbj','dept-qbj-ent-ophth','QBJ-D128','黄文银','主任医师','毕业于西南医科大学口腔医学系，四川大学华西医学院耳鼻喉科学在职研究生，华西MBA。从事眼科及耳鼻咽喉科专业20余年，擅长耳鼻喉、头颈外科、眼科常见病、多发病的诊治，尤其擅长鼻内镜手术、嗓音病、腺样体、耳鸣综合治疗，腮腺头颈部肿瘤治疗及眼底病治疗。','周一、周四上午，周二、周三、周日全天','#315b79','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-129','hospital-qbj','dept-qbj-ent-ophth','QBJ-D129','邱英','副主任医师','毕业于川北医科大学临床医学系本科，从事眼科及耳鼻咽喉科临床工作20余年，对眼科及耳鼻咽喉科常见病、多发病的临床治疗经验丰富，尤其擅长于难治性鼻窦炎，咽喉炎，声带疾病，顽固性耳鸣等疾病的治疗。','周一、周二、周四、周六全天，周五上午','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-130','hospital-qbj','dept-qbj-ent-ophth','QBJ-D130','王红雨','副主任医师','1994年毕业泸州医学院口腔医学系，1996年四川省人民医院耳鼻喉科进修，2008年华西耳鼻喉头颈外科进修，成都市青白江区人民医院头颈外科儿童组组长。主要擅长耳鼻咽喉、头颈外科多发病、常见病的诊断治疗。','轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-131','hospital-qbj','dept-qbj-ent-ophth','QBJ-D131','秦维立','主治医师','毕业于西南医科大学，从事眼科及耳鼻咽喉科专业15年，IAOA(国际角膜塑形镜协会)会员，验光师，眼镜定配工。主要从事眼科及耳鼻咽喉多发病、常见病的诊断治疗。擅长白内障及青光眼个性化治疗，糖尿病眼底病及甲状腺相关眼病、屈光不正及儿童斜弱视的诊断及治疗，RGP及角膜塑形镜的验配。','周二、周三、周五、周六、周日全天','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-132','hospital-qbj','dept-qbj-ent-ophth','QBJ-D132','魏苑秋','主治医师','毕业于川北医学院临床医学系，在成都市第二人民医院完成耳鼻咽喉头颈外科住院医师规范化培训。擅长耳鼻咽喉科、头颈外科疾病诊治。','轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-133','hospital-qbj','dept-qbj-ent-ophth','QBJ-D133','袁强','主治医师','毕业于重庆医科大学，从事临床工作近10年，擅长眼科常见病、多发病的诊治。','轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-134','hospital-qbj','dept-qbj-ent-ophth','QBJ-D134','黄宇','医师','硕士研究生，毕业于西南医科大学耳鼻咽喉科学专业，在西南医科大学附属医院完成耳鼻咽喉科专业住院医师规范化培训。擅长耳鼻咽喉科常见病、多发病的诊疗。','轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-135','hospital-qbj','dept-qbj-ent-ophth','QBJ-D135','徐季炜','医师','毕业于川北医学院，成都西部战区总医院完成耳鼻咽喉科专业住院医师规范化培训。擅长耳鼻咽喉科常见病、多发病的诊疗。','轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-136','hospital-qbj','dept-qbj-ent-ophth','QBJ-D136','冉宏运','医师','硕士研究生，毕业于山东第二医科大学眼科学专业，在潍坊市人民医院、潍坊眼科医院完成眼科专业住院医师规范化培训。主要研究方向为眼底病。熟悉眼科白内障、玻璃体视网膜等相关疾病的诊治，曾参与申请省级自然基金一项，市级软科学研究项目一项，发表sci论文1篇及核心期刊论文3篇，申请专利1项。','轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-137','hospital-qbj','dept-qbj-ent-ophth','QBJ-D137','肖娜','医师','硕士研究生，眼科医师。毕业于重庆医科大学。熟悉眼科常见病及多发病的临床诊断与治疗，擅长泪道疾病、白内障、结膜炎、干眼症、糖尿病视网膜病变等相关疾病诊治。已发表相关专业中文核心期刊及SCI论文多篇，多次参与国家级及省级学术交流会议。','轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-138','hospital-qbj','dept-qbj-stomatology','QBJ-D138','张勇','科室主任、副主任医师','2001年毕业于泸州医学院（现西南医科大学）口腔医学系，研究生学历，分别于2005、2014、赴四川大学华西口腔医学院修复科、种植科进修学习，2023年赴成都市第二人民医院口腔科进修学习，现任四川省口腔医学会牙周专委会委员、四川省妇幼协会口腔医学分会委员、成都市医学会口腔分会委员、青白江区医学会口腔专业主任委员、成都市口腔医疗质量控制中心聘任专家、青白江区口腔医疗质量控制中心主任。擅长牙体牙髓病、牙周病的诊治，美容修复前牙缺损、缺失及着色牙，贴面、嵌体、全冠修复牙体缺损，活动、固定、种植修复牙列缺损（失），各种复杂牙、埋伏牙、阻生牙拔除，儿童、成人错颌畸形的活动、传统固定、隐形矫治。','周二、周四上午','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-139','hospital-qbj','dept-qbj-stomatology','QBJ-D139','孙勇','主治医师','于1989年参加工作，擅长内科学，口腔修复学，齿槽外科的诊治及处理，对口腔常见病、多发病有丰富的诊治经验。','周一至周日 轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-140','hospital-qbj','dept-qbj-stomatology','QBJ-D140','代青芸','主治医师','硕士，毕业于四川大学华西口腔医学院。中华口腔医学会会员，发表核心期刊及SCI论文数篇。对口腔常见病和多发病的诊断及系统治疗具有丰富经验。擅长：复杂牙、阻生牙的微创拔除，牙体缺损、牙体缺失及牙列缺损（失）的各类修复治疗，常见牙体牙髓病、牙周病的诊治，儿童错颌畸形的早期干预。','周一至周日 轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-141','hospital-qbj','dept-qbj-stomatology','QBJ-D141','孙秋艳','主治医师','毕业于川北医学院口腔医学系，口腔美容主诊医师，从事临床口腔医疗11年，熟练掌握口腔各类疾病的诊断与治疗；擅长各类龋病与牙体 缺损疾病的根管治疗、美学树脂充填与贴面嵌体修复治疗；各类牙列缺损的固定修复与活动修复；各类复杂牙、多生牙及阻生牙拔除，颌面部包块切除术；乳牙反合（地包天）矫治及替牙期早期干预治疗，乳牙树脂、金属预成冠修复治疗。','周一至周日 轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-142','hospital-qbj','dept-qbj-stomatology','QBJ-D142','王璐','主治医师','毕业于西安医学院，曾在成都市第五人民医院规培三年，擅长牙体牙髓疾病，现代根管治疗术，口腔固定、活动义齿修复、前牙美学修复（美学树脂充填，瓷贴面、嵌体修复），种植牙修复。口腔颌面外科疾病的诊治（微创拔除埋伏阻生齿、复杂牙及处理齿槽外科和局麻下门诊小手术），儿童牙颌面发育畸形的早期预防性及阻断性矫治。','周一至周日 轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-143','hospital-qbj','dept-qbj-stomatology','QBJ-D143','黄美','主治医师','2015年毕业于泸州医学院，曾在口腔全科规范化培训3年。赴四川大学华西口腔医院牙体牙髓科进修学习，擅长口腔内科学(牙体牙髓疾病的诊治，微创牙体修复，前牙复合树脂美学修复，显微根管治疗术)，口腔修复学(活动修复，固定修复，种植修复，美学修复)，口腔外科学(阻生齿及复杂牙拔除，齿槽外科疾病)的诊治及处理。','周一至周日 轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-144','hospital-qbj','dept-qbj-stomatology','QBJ-D144','刘博立','主治医师','健康口腔推广大使，本科毕业于长沙医学院口腔医学系 曾于重庆医科大学附属第一医院颌面外科规范化培训3年，从事口腔临床工作7年，对口腔常见病和多发病的诊断和系统治疗具有丰富经验。擅长复杂阻生齿拔除术、微创拔牙术、口腔微创种植术、现代根管治疗术、牙体缺损充填、前牙美学贴面修复、全瓷及嵌体修复、儿童早期矫正、根尖手术、牙周牙槽手术、牙再植术等。曾获得“成都市窝沟封闭技能大赛第一名”“青白江区职业健康达人”“青白江区医保业务骨干”“青白江区人民医院优秀医生”“青白江区人民医院优秀带教老师”等荣誉证书。','周一至周日 轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-145','hospital-qbj','dept-qbj-stomatology','QBJ-D145','罗祥','主治医师','硕士研究生，中华口腔医学会牙体牙髓病学专业委员会专科会员，毕业于西南医科大学口腔医学专业，于西南医科大学附属口腔医院完成口腔全科住院医师规范化培训，具有较丰富的临床诊疗经验。擅长：复杂牙、阻生齿的微创拔除，颌面部包块切除术，牙列缺损（失）的活动义齿、固定义齿（包括种植牙）修复，以及龋病、牙髓疾病、根尖周疾病等的诊断及治疗。','周一至周日 轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-146','hospital-qbj','dept-qbj-stomatology','QBJ-D146','魏明巧','医师','毕业于川北医学院口腔医学系，口腔健康推广大使，口腔医疗质量控制中心秘书，从事口腔医疗七年余，熟练掌握口腔各类疾病的诊断与治疗；擅长各类龋病与牙体缺损疾病的现代根管治疗、前牙美学树脂充填与美学贴面修复治疗；后牙美学树脂充填修复以及嵌体修复治疗；各类牙列缺损的固定修复（全瓷冠修复、种植修复） 与活动修复（老年人活动全口义齿修复及各类局部可摘义齿修复）；各类复杂牙、多生牙及阻生牙拔除，颌面部包块切除术；乳牙反合（地包天）矫治及替牙期早期干预治疗，乳牙树脂、金属预成冠修复治疗。','周一至周日 轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-147','hospital-qbj','dept-qbj-stomatology','QBJ-D147','郑敏','主治医师','硕士，毕业于西南医科大学口腔医学专业，发表核心期刊文章数篇，干西南医科大学附属口腔医院完成口腔全科住 院医师规范化培训，擅长牙体缺损的直接美学修复（树脂）和间接美学修复（全冠、贴面、嵌体等），擅长缺牙的活动和固定修复（种植牙，固定桥等），对显微根管治疗、残冠残根的保存、阻生齿埋伏牙的拔除、牙周病、牙龈出血和牙齿松动等的治疗具有丰富经验。','周一至周日 轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-148','hospital-qbj','dept-qbj-stomatology','QBJ-D148','马宇熙','主治医师','硕士，本科毕业于南昌大学口腔医学院，硕士研究生毕业于西南医科大学口腔医学院。已完成三年口腔全科规范化培训并于西南医科大学附属口腔医院系统进行两年口腔修复学的培训，研究生期间发表学术论文数篇。擅长:美学微创修复(贴面、嵌体、美学树脂补牙等)，固定义齿、活动义齿及种植义齿修复；成人及儿童各类龋病、牙髓病、根尖周病及牙体缺损的治疗；阻生齿、埋伏牙、残冠残根等的微创拔除。','周一至周日 轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-149','hospital-qbj','dept-qbj-stomatology','QBJ-D149','唐柯欣','医师','毕业于遵义医科大学口腔医学专业，于成都大学附属医院完成口腔全科住院医师规范化培训。擅长前牙美学修复（树脂充填、贴面、全冠）、牙体牙髓病的现代根管治疗、牙槽外科（复杂牙、阻生牙、多生牙）、牙列缺失（活动义齿、固定义齿）等常见病的诊治，乳牙反颌（地包天）及儿童牙颌面发育畸形的早期干预治疗。','周一至周日 轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-150','hospital-qbj','dept-qbj-stomatology','QBJ-D150','余侠','主治医师','硕士研究生，口腔正畸学硕士，毕业于西南医科大学。时代天使隐形矫治认证医师，中华口腔医学会正畸专委会会员，发表核心期刊、SCI数篇。擅长常见青少年及成人各类错颌畸形的矫治、儿童乳牙反合（地包天）的诊治、替牙期错颌畸形的预防和干预。熟练掌握龋病、根尖周病、牙体缺损的诊断和治疗，牙列缺损的固定修复与活动修复，复杂牙及阻生牙拔除术。','周一至周日 轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-151','hospital-qbj','dept-qbj-stomatology','QBJ-D151','徐婷','主治医师','中华口腔医学会会员，曾在三甲口腔专科医院重庆医科大学附属口腔医院进行为期三年的口腔修复学培训，并攻读研究生。擅长各类牙齿缺损、牙列缺失的修复：口腔固定修复（桩核冠、粘接桥、种植牙、嵌体等），活动义齿修复；前牙变色、缝隙等的微创美学修复；阻生牙、埋伏牙、复杂牙、多生牙的微创拔除术；成人及儿童牙体牙髓疾病的诊治（龋齿充填、根管治疗、根尖手术等）；牙周病的诊治等。','周一至周日 轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-152','hospital-qbj','dept-qbj-stomatology','QBJ-D152','高鑫','医师','硕士研究生，毕业于重庆医科大学，中华口腔医学会口腔预防医学专科会员，口腔健康推广大使，在重庆医科大学附属口腔医院完成三年住院医师规范化培训，发表学术论文数篇。擅长：各类牙齿微创拔除、牙体牙髓病及显微牙科的治疗与修复、牙周系统治疗、口腔种植牙和固定义齿修复牙列缺损等。','周一至周日 轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-153','hospital-qbj','dept-qbj-emergency','QBJ-D153','刘航','科室主任、主治医师','毕业于四川大学，曾在四川大学华西医院胃肠外科进修学习。四川省康复医学会胃肠外科专委会委员 、四川省医传会胃食管反流病专委会常务委员、成都市抗癌协会消化道肿瘤 MDT 专业委员会委员、成都市抗癌协会胃癌专业委员会委员、全国卫生产业企业管理协会疝和腹壁外科学术委员会委员、四川省医师协会第三届疝与腹壁专业学组委员、四川天府新区医学会疝与腹壁外科专业委员会第一届委员会常务委员。','周一至周五','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-154','hospital-qbj','dept-qbj-emergency','QBJ-D154','何兴元','副主任医师','本科学历，从事急诊急救专业20多年，擅长多种急、危、重症的抢救，对急性创伤、多发伤、休克，急性中毒、心衰、呼吸衰竭、卒中等急、危、重症的抢救有丰富的临床经验，曾多次组织突发事件、群伤的抢救。','周一至周五','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-155','hospital-qbj','dept-qbj-nursing','QBJ-D155','张银萍','临床营养科副主任、营养师、、护师','四川省预防医学会医院临床营养分会委员，四川省中医药学会营养与食疗专委会委员，成都市临床营养质量控制中心专家组成员。擅长危重患者的营养治疗、妊娠合并糖尿病的营养管理、辩证施膳、PICC置管、PICC导管护理及静疗常见并发症的处理。 如需营养咨询，请到医技楼二楼。','PICC门诊：轮换出诊；临床营养科：周二、周四上午','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-156','hospital-qbj','dept-qbj-nursing','QBJ-D156','何利琼','主管护师','2012年在四川省人民医院接受静脉治疗专科护士培训，取得静脉治疗专科护士证，擅长PICC静脉穿刺及日常维护，解决PICC相关疑难问题。','PICC门诊：轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-157','hospital-qbj','dept-qbj-nursing','QBJ-D157','高微','主管护师','从事临床护理10+年，先后在四川省人民医院、四川大学华西医院进修学习取得静脉输液治疗专科护士证和肿瘤专科护士证，擅长肿瘤专科护理，静脉输液并发症的预防及处理，PICC、CVC、输液港维护，对带管期间出现的并发症处理具有较强的临床经验。','PICC门诊：轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-158','hospital-qbj','dept-qbj-nursing','QBJ-D158','郑焱','护师','静脉输液治疗专科护士 从事临床护士10年，在四川省肿瘤医院进修学习取得静脉输液治疗专科护士证和PICC置管资质，擅长肿瘤专科护理，静脉输液并发症的预防及处理，PICC、CVC、输液港的维护。','PICC门诊：轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-159','hospital-qbj','dept-qbj-nursing','QBJ-D159','夏婷婷','主管护师','伤口造口 门诊：轮换出诊 伤口、造口专科护士， 从事伤口造口工作九年，擅长各类急、慢性伤口的护理与治疗，对肠造口、泌尿造口的护理和造口及造口周围并发症的处理有丰富的经验。','轮换出诊，具体以当日排班为准','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-160','hospital-qbj','dept-qbj-nursing','QBJ-D160','周菡梅','主管护师','伤口造口 门诊：轮换出诊 伤口、造口专科护士，从事伤口造口门诊工作多年，擅长压疮、糖尿病足、动静脉性溃疡等疑难伤口的处理。','轮换出诊，具体以当日排班为准','#765a79','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-161','hospital-qbj','dept-qbj-neurosurgery','QBJ-D161','路敏','科室主任、副主任医师','硕士研究生，从事神经外科专业20余年。擅长：垂体瘤、脊髓肿瘤疾病、动脉瘤、三叉神经痛、面肌痉挛、小脑扁桃体下疝、颅脑外伤、高血压脑出血及其他颅内肿瘤的诊治。曾于2019年6月至8月赴德国交流学习。','轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-162','hospital-qbj','dept-qbj-neurosurgery','QBJ-D162','刘朝余','科室副主任、副主任医师','毕业于川北医学院，从事神经外科专业近20余年。擅长神经外科常见颅脑肿瘤、重型颅脑损伤的救治，高血压脑出血的显微外科手术治疗，脑血管疾病的手术治疗。擅长神经脊柱疾病的诊治包括：退行性病变如颈椎病腰椎间盘突出症的手术治疗；占位性病变如椎管内占位、骶管囊肿的手术治疗；颅底畸形如寰枢椎脱位、环枕融合、小脑扁桃体下疝（chiari畸形）的手术治疗；脊柱损伤的开放内固定融合手术治疗。','轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-163','hospital-qbj','dept-qbj-neurosurgery','QBJ-D163','孙南泉','副主任医师','2003年毕业于华北理工大学医学院，2010年一2011年在四川大学华西医院神经外科进修学习，期间参与显微镜技术丶血管吻合技术培训。擅长：颅脑外伤，脑出血，颅内各类动脉瘤，颅脑肿瘤，颅颈交界畸形，脊髓内外血管病变及肿瘤，癫痫、面瘫及三叉神经痛功能神经等疾病治疗，熟练掌握显微镜及神经内镜技术，特别在神经重症抢救治疗、颅内动脉瘤夹闭术、显微镜下微创脑内血肿清除术、颅脑肿瘤诊治方面有丰富经验。','轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-164','hospital-qbj','dept-qbj-neurosurgery','QBJ-D164','任飞亚','副主任医师','曾先后三次到华西附一院进修学习，多次参与华西医院组织的神经介入拓展训练，显微血管吻合培训，神经内镜操作培训等。学术造诣：区内首先开展了神经外科介入治疗，应用于临床10年。区内首先开展颅内动脉瘤神经介入栓塞、血管畸形神经介入栓塞、头颈部血管狭窄神经介入支架置入、全脑血管造影检查等神经介入手术。青白江区内首先开展脑干血肿开颅清除手术、脑内血肿开颅微创清除手术，前颅底及后颅窝窦旁巨大肿瘤切除手术。近年来开展新技术新项目7项。发表核心期刊论文及科普文章十余篇 擅长/精通：擅长神经外科介入治疗，颅脑外伤、脑出血、颅内各类动脉瘤、颅脑肿瘤、功能神经等领域疾病诊疗，熟练掌握显微镜及神经内镜、DSA机技术，特别是脑血管疾病微创手术治疗及介入手术治疗，颅脑肿瘤手术功能保护，神经外科危急重症围手术期诊治方面有丰富经验。','轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-165','hospital-qbj','dept-qbj-ortho','QBJ-D165','何泽壁','科室主任、主任医师','成都医学会骨科专委会委员、四川省国际交流与医学促进会创伤与骨科专科分会委员、成都市骨科质控中心委员、《骨科围手术期管理手册》编委。曾在北京协和医院骨科进修学习，后经四川省卫健委选拔到德国柏林helios综合医院骨科研修。擅长内镜下微创手术治疗颈腰椎间盘突出症、腰椎滑脱、椎管狭窄症等以及颈肩腰腿疼痛的阶梯治疗，并率先在青白江及周边地区开展椎间孔镜手术、颈椎内固定手术及膝关节置换手术等。','周四上午','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-166','hospital-qbj','dept-qbj-ortho','QBJ-D166','杨延全','副主任医师','从事骨科专业20余年，擅长颈椎病、腰椎间盘突出症、腰椎管狭窄症、腰椎滑脱的诊治手术，四肢多发骨折及骨病的手术诊疗，以及髋膝关节置换。','周一全天、周二上午、周四、周五下午','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-167','hospital-qbj','dept-qbj-ortho','QBJ-D167','李鹏','副主任医师','硕士研究生，四川省全科医师师资，师从于我国著名骨科专家王跃教授，从事骨科专业15余年，先后获得“成都市援藏先进个人"，“医德医风先进个人”,"成都市青白江区人民医院首届十佳医师”等称号。擅长关节镜手术，髋、膝、肩关节置换，腰椎间盘突出、复杂髋部、肘部骨折手术、狭窄性腱鞘炎的针刀微创手术治疗等技术。','周五上午','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-168','hospital-qbj','dept-qbj-ortho','QBJ-D168','周进','副主任医师','医学硕士，毕业于重庆医科大学，从事骨科临床工作8年，对四肢创伤骨科、脊柱创伤、脊柱及骨关节退变、股骨头坏死等疾病的诊治有丰富的经验。','周二下午、周三全天、周六上午','#8a594d','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-169','hospital-qbj','dept-qbj-ortho','QBJ-D169','郑博','主治医师','硕士，毕业于成都医学院，在成都医学院第一附属医院完成专科规培。对四肢骨折等多发创伤骨折、骨质疏松、髋、膝、肩、肘等关节疾病具有丰富的临床经验，对脊柱疾病亦具有一定临床经验。','轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-170','hospital-qbj','dept-qbj-ortho','QBJ-D170','周浩','医师','医学硕士，2020年毕业于西南医科大学，从事骨科相关临床工作5年。擅长髋、膝关节置换，保髋及保膝治疗，四肢骨折等骨关节疾病的临床诊治，以第一作者身份在国内核心期刊发表论文2篇。','轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-171','hospital-qbj','dept-qbj-ortho','QBJ-D171','陈攀','医师','医学本科，2022年在简阳市人民医院完成骨科专培。擅长对创伤骨科常见骨折的诊治及手术，对髋膝关节骨病、颈腰椎病的诊治也有一定临床经验。','轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-172','hospital-qbj','dept-qbj-ortho','QBJ-D172','李浩','医师','医学硕士，毕业于成都医学院。对四肢骨折、髋膝关节及骨质疏松等骨关节疾病具有丰富的临床经验，对脊柱相关疾病亦具有一定临床经验。','轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-173','hospital-qbj','dept-qbj-urology','QBJ-D173','贾其磊','科室主任、主任医师','医学博士，“四川省学术和技术学科带头人后备人选”；四川省医师协会泌尿外科专委会膀胱癌学组成员;四川省预防医学会盆底修复与重建委员会委员；获国家实用新型专利四项；2019年曾在意大利Salerno大学医院研修三个月。擅长膀胱肿瘤,肾脏肿瘤,前列腺疾病,泌尿系结石等治疗,对尿道狭窄,尿失禁,排尿障碍,男科疾病，小儿泌尿等疾病的微创治疗。','周一全天、周日轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-174','hospital-qbj','dept-qbj-urology','QBJ-D174','郑泽贵','副主任医师','毕业于兰州军区医学院。从事泌尿外科工作30多年、擅长泌尿外科常见病多发病的诊治、发表相关论文5篇、熟练掌握泌尿外科微创手术、前列腺电切手术、前列腺剜出手术、膀胱结石、肿瘤根治、输尿管结石钬激光治疗、肾肿瘤根治、经皮肾镜钬激光碎石治疗、前列腺癌根治等。对小儿泌尿外科微创治疗有较好疗效，对泌尿生殖系的诊疗有自己的诊治方法。','周二全天、周三下午、周四全天、周日轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-175','hospital-qbj','dept-qbj-urology','QBJ-D175','刘文兵','副主任医师','毕业于川北医学院临床医学系，四川省泌尿外科青年委员会成员，青白江区泌尿外科专委会副主任委员，从事泌尿外科专业临床工作15年。2015年在第三军医大学西南医院进修泌尿微创治疗，2019年在南方医科大学珠江医院培训局麻经皮肾镜碎石术及前列腺剜除术，2019年在上海交通大学第六人民医院培训尿道修复重建。擅长泌尿外科微创手术治疗，尤其对肾结石、输尿管结石、尿道及膀胱结石的整体治疗，前列腺增生微创治疗治疗有独到之处。可开展局麻经皮肾镜取石，输尿管镜取石，电子软镜取石，前列腺等离子剜除术，精道镜技术等。对前列腺炎、精囊炎等男科疾病，女性尿失禁治疗也有丰富的临床经验。','周三上午、周五下午、周日轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-176','hospital-qbj','dept-qbj-urology','QBJ-D176','汪海波','副主任医师','成都医学院临床医学专业本科毕业，曾在军区总医院进修学习，多次参加全国及省级培训学术会议，擅长泌尿系结石、前列腺增生、前列腺炎疾病等泌尿外科常见疾病的诊治，擅长体外碎石、输尿管镜碎石、经尿道前列腺电切、腹腔镜下精索静脉曲张高位结扎、腹腔镜下肾囊肿去顶减压等微创手术治疗。','轮换出诊','#315b79','active','2026-08-28T00:00:00+08:00')
INSERT INTO doctors (id,hospital_id,department_id,code,name,title,specialty,schedule_text,avatar_color,status,updated_at) VALUES
('doctor-qbj-177','hospital-qbj','dept-qbj-urology','QBJ-D177','张策伟','主治医师','硕士研究生，本科毕业于三峡大学临床医学专业，研究生毕业于锦州医科大学，同期于锦州医科大学附属第一医院完成国家级规培，为泌尿外科专业型硕士。硕士期间的研究方向为泌尿系结石评分系统。擅长泌尿外科常见疾病的规范化诊疗，能熟练完成膀胱镜、体外冲击波碎石等操作。','周二上午、周六轮换出诊','#7a5f45','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-178','hospital-qbj','dept-qbj-urology','QBJ-D178','王宇飞','主治医师','2014年毕业于成都中医药大学临床医学系本科毕业，从事泌尿外科专业临床工作，在德阳市人民医院完成住院医师规范化培训，擅长泌尿系统疾病的诊治工作，能熟练地完成膀胱镜、输尿管镜手术、体外冲击波碎石等。','轮换出诊','#765a79','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-179','hospital-qbj','dept-qbj-urology','QBJ-D179','唐鹏','主治医师','2013年毕业于泸州医学院（现西南医科大学）临床医学系本科毕业，从事泌尿外科专业临床工作，在成都市第二人民医院完成住院医师规范化培训，擅长泌尿系统疾病的诊治工作，擅长经会阴前列腺穿刺（前列腺Ca早期筛查），能熟练地完成膀胱镜、输尿管镜手术、体外冲击波碎石。','周一上午、周六轮换出诊','#44736d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-180','hospital-qbj','dept-qbj-urology','QBJ-D180','梁晨轩','医师','泌尿外科专业型硕士，毕业于河北医科大学。具备扎实临床经历，熟悉泌尿外科的常见病、多发病的诊疗过程。熟悉并掌握膀胱镜、腹腔镜、输尿管 (软) 镜、 电切镜的使用。','周六轮换出诊','#8a594d','active','2026-08-28T00:00:00+08:00'),
('doctor-qbj-181','hospital-qbj','dept-qbj-urology','QBJ-D181','黄宏达','医师','泌尿外科专业型硕士，毕业于成都医学院。擅长泌尿外科常见病的规范化诊疗，能熟练完成膀胱镜、体外冲击波碎石等治疗。','周六轮换出诊','#176b62','active','2026-08-28T00:00:00+08:00')
