('loc-qbj-guide','hospital-qbj','GUIDE','导医服务总台','门诊楼','1F','大厅中央','咨询、分诊与院内路线指引','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-emergency','hospital-qbj','EMERGENCY','急诊科','门诊楼','1F','左侧急诊区','急危重症优先处置，院内急救电话 028-83611120','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-fever','hospital-qbj','FEVER','发热门诊','门诊楼','1F','右侧独立入口','发热患者按现场标识进入','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-registration','hospital-qbj','REGISTRATION','门诊挂号收费室','门诊楼','1F','大厅右侧','挂号、缴费与取号','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-pharmacy','hospital-qbj','PHARMACY','门诊药房','门诊楼','1F','大厅左侧','门诊取药与中药煎药室','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-lab','hospital-qbj','LAB','静脉采血室','门诊楼','2F','检验科','门诊采血与检验服务','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-icu','hospital-qbj','ICU','重症医学科','住院区域','住院区域','重症监护区','重症医学科（ICU）是青白江区首家集危重症抢救、监护及综合性治疗的重症监护治疗中心。科室集中医院优势医疗资源对急危重症患者进行救治，开展各类急性器官功能衰竭、需紧急生命支持患者，各类休克、中毒患者，严重多发伤、复合伤患者，呼吸心跳骤停需心肺脑复苏患者，各种重大、高危手术需围手术期监护、处理患者，严重、复杂感染，脓毒血症，重症急性胰腺炎，多器官功能衰竭等患者的精心监测和精确治疗，对各类危重患者抢救积累了丰富的临床经验，并抢救成功了大量的危重患者。专业特色：器官功能支持、急危重症患者监测等。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-radiology','hospital-qbj','RADIOLOGY','医学影像科','医技楼','1F','影像检查区','医学影像科是区域规模最大、技术力量最雄厚、设备最先进的医学影像检查中心，是青白江区远程影像会诊中心。科室设备总资产近4000万元。拥有128层容积VCT、1.5T超导磁共振、整板数字DR机、数字乳腺钼靶摄片系统、动态数字胃肠机、数字双能X线骨密度仪、床旁DR机等进口设备；还拥有国产64层多层螺旋CT、数字DR机等先进设备及图像处理工作站；有自助打印激光相机3台。科室建立了图像储存和传输系统（PACS）和影像信息系统（RIS），已成为数字化、网络化现代医学影像中心。','active','2026-08-28T00:00:00+08:00')
INSERT INTO hospital_locations (id,hospital_id,code,name,building,floor,zone,description,status,updated_at) VALUES
('loc-qbj-cssd','hospital-qbj','CSSD','消毒供应中心','医技楼','1F','院内工作区','消毒供应中心建筑面积865平方米，布局合理，区域划分明确，功能齐全，配备了现代化的清洗、消毒、灭菌设备，为医疗质量安全、预防医院感染提供安全保障。中心于2015年2月通过市卫生主管部门质量评价验收。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-ultrasound','hospital-qbj','ULTRASOUND','超声科','医技楼','2F','超声检查区','超声科现有医护人员24名，其中主任医师1名，副主任医师1名，主治医师13名，医师3名，护师1名，技师5名，多人曾在华西第一医院、华西第二医院、四川省人民医院、成都市第二人民医院等上级医院进修学习。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-pathology','hospital-qbj','PATHOLOGY','病理科','第一住院楼','2F','','病理科成立于2000年，为成都市青白江区病理质量控制中心。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-transfusion','hospital-qbj','TRANSFUSION','输血科','第一住院楼','2F','','输血科成立于2014年5月，承担青白江区储血点的工作；与青白江区5家医疗机构签订供血协议，保障青白江区的血液制品供应并提供血液输注相关技术指导。科室按照三级医院输血科配置要求布局建设，拥有完善的管理制度及管理体系。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-anesthesia','hospital-qbj','ANESTHESIA','麻醉科','第一住院楼','2F','手术部','麻醉科手术室目前有9个现代化层流手术间（其中百级手术间2间、万级手术间7间、负压手术间1间）及按标准配备的麻醉恢复室。每个手术间均安装有标准的中心供氧、中心吸引、废气排出系统、高级无影灯、多功能外科吊塔，均配备有先进的手术床、进口麻醉机、多参数监护仪；有先进的微量输注泵、术中体温保温设备、手术麻醉信息系统、高频电刀、超声刀、腹腔镜、除颤仪等仪器设备。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-infectious','hospital-qbj','INFECTIOUS','感染性疾病科','门诊楼','1F','发热门诊','感染性疾病科2015年9月成立，科室设置相对独立，面积800平方米，内部结构布局合理，分区清楚。设置有独立的发热、腹泻、结核、肝炎门诊和儿科发热门诊。病区设有独立的诊室、候诊区、隔离观察室、处置室、抢救室、卫生间、挂号收费室及药房，发热隔离病房设床位12张，含2张抢救床。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-picc','hospital-qbj','PICC','PICC门诊','门诊楼','2F','205','PICC适用于需要中长期静脉治疗，特别是多疗程化疗及肠外营养支持的患者，可减少病人反复穿刺的痛苦，保护外周血管，并发症少、维护简便，提高病人的生活质量。我院已能成熟开展PICC置管技术，导管维护1万余人次。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-tcm','hospital-qbj','TCM','中医科','门诊楼','2F','中医馆','中医科是集传统中医特色与现代先进中医药治疗技术于一体的大型综合性科室。科室主要治疗中医骨伤科、针灸科、推拿科、中医内妇儿外常见病多发病。开展颈椎间盘突出症、腰椎间盘突出症、各部位骨质增生、网球肘、肩周炎、面瘫、各部位骨性关节炎、早期股骨头缺血性坏死、各种肌肉劳损、各类软组织损伤，闭合性骨折脱位的手法复位、中医内妇儿外及各类杂证的治疗，以及各类亚健康人群调理。采用牵引、手法推拿复位、电针、艾灸、拔罐、中药蒸汽浴治疗、穴位注射、火针、浮针、超微针刀、放血疗法、中药外敷、中药内服等综合治疗。专业特色：中药蒸汽浴特色治疗、外敷中药特色治疗、中医治未病、超微针刀疗法、小儿推拿等。','active','2026-08-28T00:00:00+08:00')
INSERT INTO hospital_locations (id,hospital_id,code,name,building,floor,zone,description,status,updated_at) VALUES
('loc-qbj-nutrition','hospital-qbj','NUTRITION','临床营养科','门诊楼','2F','营养咨询门诊','临床营养科于2014年3月成立。科室开展营养筛查、营养评估、营养宣教，并参与临床会诊，为糖尿病、高血压、肠道疾病、围手术期病员及危重病人提供肠内营养支持治疗。负责对亚健康人群、慢性疾病（如糖尿病、高血压、冠心病）患者、特殊人群（孕妇、儿童、老年人）进行营养咨询，制定个性化、合理化的营养指导及治疗方案。科室定期向临床医护人群、病员及家属、社区居民进行营养与健康知识讲座，坚持为广大居民群众宣传健康膳食知识，提供科学合理的饮食指导。开设营养咨询门诊，出诊时间：周二下午。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-wound','hospital-qbj','WOUND','伤口造口门诊','门诊楼','2F','207','伤口造口专科门诊开设于2014年，采用先进的治疗理念，为患者提供伤口造口的护理及治疗。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-ped','hospital-qbj','PED','儿科','门诊楼','2F','儿科区','儿科是青白江区优势学科，是集儿童医疗、保健、科研教学为一体的成建制儿童专科，科室除长期开展儿童保健，儿童常见病、多发病的诊治外，对儿童疑难病症、危急重症的治疗、抢救具有丰富的成功经验。专业特色：儿科新生儿室条件优越，符合院感流程及要求，为新生儿疾病的诊治提供有力的硬件保障；儿童保健及生长指导。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-stomatology','hospital-qbj','STOMATOLOGY','口腔科','门诊楼','2F','具体诊室以当日排班为准','口腔科拥有丰富的口腔医疗技术资源，能开展口腔种植技术、口腔粘膜病的系统诊治、无痛微创拔牙技术、活动翼矫治牙列不齐等牙颌面畸形、全瓷冠桥修复、牙科X光CR读片系统等。临床开展的亚专业有牙体牙髓科、牙周科、牙槽外科、口腔颌面外科、口腔修复、口腔正畸等。专业特色：埋伏阻生牙拔除术、烤瓷贴面技术、牙种植技术。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-obgyn','hospital-qbj','OBGYN','妇产科','门诊楼','2F','妇产科区','妇产科是全区孕产妇保健、分娩中心，妇产科疾病诊治及产科急救中心，建立有高危妊娠规范化管理和诊疗系统，和院内重症医学科、麻醉科、输血科、介入肿瘤科、内分泌及肾病内科等组建了MDT急救团队，承接区内和周边地区各种高危孕产妇的救治，对严重产后出血、妊娠期高血压疾病、妊娠合并严重的内外科疾病等危重症抢救有丰富的临床经验。现已发展为全区领先水平的集医疗、教学、科研、保健、康复为一体的现代化科室。2019年7月与四川省科学院·四川省人民医院建立生殖专科联盟医院并增设了生殖内分泌与不孕专科门诊，2021年与四川大学华西第二医院建立盆底疾病专病联盟。近年来，微创手术逐步取代传统手术，我科在成功开展阴式系列手术，经腹腔镜、冷刀宫腔镜手术的基础上，于2019年率先在区内开展了单孔腹腔镜手术。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-rehab','hospital-qbj','REHAB','康复医学科','门诊楼','2F','外科区','康复医学科是成都市医学重点专科建设项目，青白江区医疗康复定点医疗机构，青白江区工伤急性期康复定点医疗机构。以现代康复医学理论及康复治疗技术，结合中医传统康复为诊疗特色的临床专科。科室常规开展康复评定、运动治疗、作业治疗、物理因子治疗、言语吞咽治疗、中医康复治疗、康复工程等一系列康复技术。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-nursing','hospital-qbj','NURSING','护理组','门诊楼','2F','PICC/伤口造口门诊','院方医生资料中已收录护理组专家与出诊信息。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-urology','hospital-qbj','UROLOGY','泌尿外科','门诊楼','2F','外科区','泌尿外科是成都市医学重点专科建设项目，在成都市北部片区具有较强影响力，以泌尿系统结石、膀胱肿瘤、前列腺疾病为临床和科研特色，近年来，已全面开展泌尿外科相关技术项目，涵盖了几乎所有的病种，科室微创手术率达90%，几乎取代传统开放手术。科室主任、学科带头人贾其磊主任医师为泌尿外科专业博士，从事临床工作20余年，擅长前列腺疾病、泌尿系结石、尿道修复重建、泌尿系畸形等疾病的治疗，近年来在国内外医学杂志上发表论文10余篇（含SCI论文），获市级科技进步奖1项，承担厅、市级科研课题3项，曾在意大利UNIVERSITÀ DEGLI STUDI DI SALERNO研修三个月。技术名称：根治性膀胱全切+尿流改道术','active','2026-08-28T00:00:00+08:00')
INSERT INTO hospital_locations (id,hospital_id,code,name,building,floor,zone,description,status,updated_at) VALUES
('loc-qbj-breast-thoracic','hospital-qbj','BREAST_THORACIC','甲乳胸外科','门诊楼','2F','外科区','甲乳胸外科是以甲状腺、乳腺、胸外科为专业特色的科室。科室拥有乳腺钼靶、乳腺微创旋切机、移动查房车、胸腔镜及超声刀等先进设备。科室医护团队专业、成熟，主要承担甲状腺、乳腺、胸外方面的疾病救治，对乳房整形、乳腺良恶性肿瘤、甲状腺结节、甲状腺癌、肺结节、肺癌、食管癌、胸部外伤等疾病诊治具有丰富的临床经验。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-pain','hospital-qbj','PAIN','疼痛科','门诊楼','2F','中医馆','疼痛科是青白江区率先开设的疼痛疾病治疗专科，在成都市北部片区具有较强影响力。科室开展针对疼痛的各种保守治疗、神经阻滞治疗以及采用各种疼痛介入疗法治疗颈、腰椎间盘突出症，颈、腰椎病，带状疱疹后神经痛，三叉神经痛，手术后疼痛等多种临床常见慢性疼痛及复杂顽固性疼痛。专业特色：臭氧相关治疗；微创介入术。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-ent-ophth','hospital-qbj','ENT_OPHTH','眼科及耳鼻咽喉科','门诊楼','2F','五官科区','眼科及耳鼻咽喉科是诊治眼、耳、鼻、喉科常见病、多发病、疑难病的专业科室，开展或协作开展眼耳鼻喉及口腔科常规手术及部分高难度手术。开展睡眠呼吸监测(鼾症)、白内障(超声乳化技术)、低温等离子技术等特色技术。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-neurosurgery','hospital-qbj','NEUROSURGERY','神经外科','门诊楼','2F','外科区','神经外科是青白江区优势专科，建有神经外科重症监护室。常规开展颅脑脊柱脊髓损伤综合救治，脑血管病诊治，神经系统肿瘤诊治，周围神经系统疾病诊治等业务。专业特色：重型颅脑损伤救治（包括手术）、高血压脑出血手术治疗、脑血管病诊治（颅内动脉瘤开颅夹闭手术、颅内动脉瘤血管内栓塞术、颅内动静脉畸形切除术、颈内动脉狭窄内膜剥脱术等）、颅内椎管内肿瘤切除术、脊柱椎间盘脱出等退行性病变的手术治疗等。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-anorectal','hospital-qbj','ANORECTAL','肛肠科','门诊楼','2F','中医馆','肛肠科是医院极具特色的中西医结合专科，在肛肠疾病诊疗方面，采用中药熏洗、内服、外敷、结扎、挂线等中医药传统疗法，结合现代诊疗技术，形成一套完善的特色诊疗体系。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-gi-surgery','hospital-qbj','GI_SURGERY','胃肠肝胆外科','门诊楼','2F','外科区','普外科是以胃肠、疝、肝、胆、胰、脾、烧伤为专业特色的科室。开展腹腔镜结、直肠癌根治术，规范化胃癌标准根治术，腹腔镜胆囊、阑尾、疝修补术，双镜联合胆道取石术，MDT（多学科参与）肝癌规范化治疗，半肝切除术，肝门胆管癌根治术，腔镜下肝血管瘤剥除术，胆总管先天性囊肿切除术，胰十二指肠切除术，肝脾破裂手术，还开展日间手术、加速康复外科，极大缩短住院时间，深受患者好评。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-thoracic','hospital-qbj','THORACIC','胸外科','门诊楼','2F','外科区','我院胸外科是四川省基层医院微创胸外科能力提升项目建设单位，通过华西医院专家的指导及技术下沉，我院胸外科专业团队独立开展了大量新业务、新技术，如全胸腔镜下肺叶、肺段切除术，CT引导下肺结节定位病损切除术，胸廓畸形矫正手术，利用3D打印技术行胸壁病损切除及重建手术等，并开展了领先的诊疗模式--肺结节MDT（多学科联合会诊）。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-ortho','hospital-qbj','ORTHO','骨科','门诊楼','2F','外科区','骨科以创伤骨科、脊柱外科、关节外科、胸外科、运动医学为临床和科研特色，是青白江区优势学科。近年来，运动医学及脊柱内镜等微创新技术在骨科得到迅猛发展，各类疑难及重大手术剧增，例如关节镜下前后交叉韧带重建术、关节镜下腘窝囊肿切除术，脊柱内镜（UBE及椎间孔镜）下微创椎间盘切除术、椎管成形术、椎间融合、经皮置钉内固定术，颈椎寰枢关节骨折脱位切开复位内固定术，PKP（后路经皮球囊扩张椎体成形术），DAA（直接前方入路）微创全髋关节置换术，复杂髋膝关节置换及翻修术，全腔镜下食管癌根治术、肺癌根治术、纵膈占位切除、膈疝修补、食管胃交界癌根治术、心包手术、肺大疱切除等。专业特色：创伤、脊柱、关节、胸外、运动医学各亚专业医疗水平齐头并进的同时继续向微创化及复杂性手术深入发展。','active','2026-08-28T00:00:00+08:00')
INSERT INTO hospital_locations (id,hospital_id,code,name,building,floor,zone,description,status,updated_at) VALUES
('loc-qbj-psych','hospital-qbj','PSYCH','临床心理门诊','门诊楼','3F','335','我院心身睡眠医学科主要为受情绪困扰、睡眠障碍困扰、身体莫名不适等患者和家属提供帮助。目前开展门诊有心身睡眠门诊和心理咨询门诊。采用药物治疗结合心理治疗的生物-医学-社会医疗模式。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-clinical-pharmacy','hospital-qbj','CLINICAL_PHARMACY','临床药学科','门诊楼','3F','321 用药咨询门诊','临床药学科成立于2016年4月，科室从事全院药事管理、临床合理用药、抗菌药物应用管理、门急诊处方点评、住院医嘱审核、药学查房、不良反应监测及上报、药学监护、用药咨询、用药重整、慢病管理、临床疑难病例讨论、临床会诊、大专院校实习生带教及其他药学工作。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-weight-mgmt','hospital-qbj','WEIGHT_MGMT','体重管理门诊','门诊楼','3F','309','院方医生资料中已收录体重管理门诊专家与出诊信息。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-health-mgmt','hospital-qbj','HEALTH_MGMT','健康管理门诊','门诊楼','3F','体检中心','院方医生资料中已收录健康管理门诊专家与出诊信息。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-child-health','hospital-qbj','CHILD_HEALTH','儿童保健科','门诊楼','3F','儿保/特需门诊区','儿童保健科简称儿保科，是集儿童生长发育，儿童保健诊疗，婴幼儿及儿童心理发育评估，婴幼儿营养与喂养于一体的临床一级专业科室，常年接收0～5岁儿童的系统儿童保健的建卡检查即儿童生长发育工作，以及散居儿童的儿保工作。科室致力于保障和促进儿童身心健康及儿童生长发育的各项临床工作。儿童保健学科包括了儿童临床医学、儿童教育学、儿童心理学、儿童营养学等多方面学科。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-endo-neph','hospital-qbj','ENDO_NEPH','内分泌及肾病内科','门诊楼','3F','内科区','内分泌及肾病内科设有门诊、住院部和血液透析室。科室在内分泌系统及肾内科疾病的诊治方面，如糖尿病及其并发症、骨质疏松的诊治方面有丰富的临床经验，能开展肾上腺疾病、甲状腺疾病、垂体疾病、内分泌性高血压、肥胖、脂代谢异常、骨软化、多囊卵巢综合征、痛风及水、电解质紊乱的诊治、尿路感染、肾小管酸中毒、慢性肾脏疾病、慢性肾功能衰竭的诊治和血液透析治疗等。专业特色：血液透析技术、四肢多普勒血流图测定、胰岛素泵治疗、带隧道带涤纶套血透导管置入术、肾穿刺活检术、经皮腔内血管成形术等。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-aesthetic','hospital-qbj','AESTHETIC','医疗美容科','门诊楼','3F','皮肤科诊区','医疗美容科门诊开展业务：','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-resp','hospital-qbj','RESP','呼吸与危重症医学科','门诊楼','3F','呼吸内科区','呼吸与危重症医学科开展急慢性呼吸道感染性疾病、气道阻塞性疾病、肺源性心脏病、呼吸衰竭、胸膜性疾病、呼吸系统肿瘤等疾病诊断治疗，肺功能检查、无创正压通气、电子支气管镜检查及治疗、呼吸内镜介入治疗（经气管镜球囊扩张治疗、经气管镜气道支架置入术、经气管镜球囊探查联合自体血难治性气胸封堵术等）、CT引导下经皮肺穿刺、胸膜活检。专业特色：气道良恶性病变的微创治疗、支气管肺泡灌洗、气道异物取出等。','active','2026-08-28T00:00:00+08:00')
INSERT INTO hospital_locations (id,hospital_id,code,name,building,floor,zone,description,status,updated_at) VALUES
('loc-qbj-resp-chronic','hospital-qbj','RESP_CHRONIC','呼吸慢病门诊','门诊楼','3F','330','院方医生资料中已收录呼吸慢病门诊专家与出诊信息。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-card','hospital-qbj','CARD','心血管内科','门诊楼','3F','心血管内科区','心血管内科是成都市医学重点专科，正在申报省级重点专科，在成都市北部片区具有较强影响力，分为A区和B区。科室与成都市第二人民医院心内科深度合作，开展心内科领域全部介入手术。专业特色：冠状动脉造影及经皮冠脉内支架植入术（包括：急性心肌梗死急诊PCI术、血栓抽吸术、分叉病变及左主干病变PCI术、冠状动脉慢性闭塞性病变（CTO）支架置入术）、主动脉内球囊反搏术、冠状动脉血管内超声（IVUS）、心脏电生理检查及三维指导下复杂心律失常射频消融术、心脏临时及永久起搏器植入术、心脏希氏束起搏、埋藏式心脏自动复律除颤器植入术（ICD）等。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-gastro','hospital-qbj','GASTRO','消化内科','门诊楼','3F','内科区','消化内科是青白江区优势专科，科室设有门诊、病区和内窥镜室。开展胃食道反流、急慢性胃炎、消化性溃疡、消化道出血、胰腺炎、胃肠道肿瘤、炎症性肠病、肠结核、结核性腹膜炎、功能性胃肠疾病；乙肝、丙肝、肝硬化失代偿期、酒精性肝炎、自身免疫性肝炎等疾病诊疗。内窥镜室开展常规胃镜、肠镜检查，无痛胃镜、肠镜检查及内镜下治疗。专业特色：肝病治疗；内镜下治疗。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-derm','hospital-qbj','DERM','皮肤科','门诊楼','3F','皮肤科诊区','皮肤科是成都市医学重点专科，是成都市第二人民医院皮肤科直接指导科室。是青白江区皮肤病性病治疗控制分中心、艾滋病治疗质控分中心。科室除开展常见皮肤病与性病诊治外，还率先在区域内开展皮肤外科、皮肤美容等技术，拥有强脉冲光治疗仪、Q开关ND：YAG激光治疗仪、超脉冲二氧化碳点阵激光治疗仪、308准分子光治疗仪等各种高端治疗仪器。电子皮肤镜检查、皮肤活检术、果酸活肤术、308准分子光相关治疗、超脉冲点阵激光相关治疗、调Q激光相关治疗及光子嫩肤术为科室特色治疗项目。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-neuro','hospital-qbj','NEURO','神经内科','门诊楼','3F','内科区','神经内科是青白江区领衔专科，开展脑梗塞、脑出血、短暂性脑缺血发作、癫痫、眩晕、偏头痛、各类脑炎、脊髓炎、重症肌无力、格林-巴利综合征、面瘫、多发性硬化、帕金森、痴呆、多系统萎缩、睡眠障碍、焦虑抑郁、脑动脉供血不足等疾病诊治。专业特色：脑血管病的预防、急救（急性脑梗塞的静脉溶栓治疗）、康复；帕金森病、癫痫、神经肌肉病、头面痛、神经系统感染性疾病的诊断与治疗。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-radiotherapy','hospital-qbj','RADIOTHERAPY','肿瘤放疗科','门诊楼','3F','320','肿瘤放疗科是专业从事肿瘤规范化诊断及治疗的临床科室，是青白江区集肿瘤预防、诊断、治疗及康复为一体的特色专科，在成都市北部片区具有较强影响力。科室承担成都市重特大疾病认定及治疗工作，是青白江区癌症防治中心、肿瘤性疾病质控中心及临终关怀质量控制中心。专业特色：肿瘤性疾病的筛查、诊断；恶性肿瘤化疗、靶向治疗、免疫治疗等；PCA镇痛技术；肿瘤深部热疗；PICC/CVC置管、输液港植入及维护。','active','2026-08-28T00:00:00+08:00'),
('loc-qbj-intervention','hospital-qbj','INTERVENTION','肿瘤血管介入科','门诊楼','3F','319','肿瘤血管介入科现有医护人员17名，床位33张，现有型号Innova3100 DSA 一台、高压注射器一台、除颤监护仪一台、呼吸机一台、穿刺活检枪一支、心电监护仪微量注射泵等各种设备。建科以来，科室坚持综合性治疗及个体化治疗相结合的原则，以“病人为中心”，开展多学科诊疗协作，精准治疗，提高患者生存期。目前是“青白江区外周介入质控中心”、“癌痛规范化诊疗培育单位”，并于2019年被授予“全国难治性癌痛规范化诊疗基地”。','active','2026-08-28T00:00:00+08:00')
